function design(site, analyse) {
  const xP = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const D = 5.5, nP = 9;
  const S = [
    ["S460 CHS168.3x5","S460 CHS168.3x6.3","S460 CHS193.7x6.3","S460 CHS193.7x8","S460 CHS219.1x8","S460 CHS244.5x8","S460 CHS273x10"],
    ["S460 CHS60.3x4","S460 CHS76.1x4","S460 CHS88.9x4","S460 CHS88.9x5","S460 CHS114.3x4","S460 CHS114.3x5","S460 CHS139.7x5","S460 CHS139.7x6.3","S460 CHS168.3x5","S460 CHS168.3x6.3"],
    ["S355 CHS33.7x2.6","S355 CHS42.4x3.2","S355 CHS48.3x3.2","S355 CHS60.3x3.2","S355 CHS60.3x4","S355 CHS76.1x3.2","S355 CHS76.1x4"]
  ];
  const nodes = [];
  for (let i = 0; i <= nP; i++) {
    nodes.push({id:`BL${i}`,x:xP[i],y:-D,z:-2.65});
    nodes.push({id:`BR${i}`,x:xP[i],y:-D,z:2.65});
  }
  const md = [];
  for (let i = 0; i < nP; i++) md.push([`BL${i}`,`BL${i+1}`,0],[`L${i}`,`L${i+1}`,0],[`L${i}`,`BL${i}`,1]);
  md.push([`L${nP}`,`BL${nP}`,1]);
  for (let i = 0; i < 4; i++) md.push([`BL${i}`,`L${i+1}`,1]);
  md.push([`BL4`,`L5`,1]);
  for (let i = 5; i < nP; i++) md.push([`L${i}`,`BL${i+1}`,1]);
  for (let i = 0; i < nP; i++) md.push([`BR${i}`,`BR${i+1}`,0],[`R${i}`,`R${i+1}`,0],[`R${i}`,`BR${i}`,1]);
  md.push([`R${nP}`,`BR${nP}`,1]);
  for (let i = 0; i < 4; i++) md.push([`BR${i}`,`R${i+1}`,1]);
  md.push([`BR4`,`R5`,1]);
  for (let i = 5; i < nP; i++) md.push([`R${i}`,`BR${i+1}`,1]);
  for (let i = 0; i <= nP; i++) md.push([`BL${i}`,`BR${i}`,2],[`L${i}`,`R${i}`,2]);
  for (let i = 0; i < nP; i++) md.push([`BL${i}`,`BR${i+1}`,2],[`BR${i}`,`BL${i+1}`,2],[`L${i}`,`R${i+1}`,2],[`R${i}`,`L${i+1}`,2]);
  let si = md.map(d => d[2]===0?5:d[2]===1?6:3);
  const build = () => ({
    note: "Pratt truss below deck, S460 main S355 bracing",
    nodes: nodes.map(n=>({...n})),
    members: md.map((d,i)=>[d[0],d[1],S[d[2]][Math.min(si[i],S[d[2]].length-1)]])
  });
  let bestD=null, bestM=Infinity;
  for (let it=0; it<30; it++) {
    const d=build(), r=analyse(d);
    if (r.error) { if (!bestD) return d; break; }
    if (r.ok && r.mass<bestM) { bestD=JSON.parse(JSON.stringify(d)); bestM=r.mass; }
    const m=r.members||[], match=m.length===md.length;
    if (r.ok) {
      let ch=false;
      if (match) {
        for (let i=0;i<md.length;i++) {
          if (si[i]>0 && m[i].util<0.35) { si[i]=Math.max(0,si[i]-2); ch=true; }
          else if (si[i]>0 && m[i].util<0.68) { si[i]--; ch=true; }
        }
        if (!ch) for (let i=0;i<md.length;i++)
          if (si[i]>0 && m[i].util<0.82) { si[i]--; ch=true; }
      }
      if (!ch) break;
    } else {
      let ch=false;
      if (match) for (let i=0;i<md.length;i++)
        if (m[i].util>0.88 && si[i]<S[md[i][2]].length-1) { si[i]++; ch=true; }
      if (!ch) for (let i=0;i<si.length;i++)
        if (si[i]<S[md[i][2]].length-1) si[i]++;
    }
  }
  return bestD||build();
}

