    md.push([`L${i}`,`BL${i+1}`,2],[`BL${i}`,`L${i+1}`,2],[`R${i}`,`BR${i+1}`,2],[`BR${i}`,`R${i+1}`,2]);
    md.push([`L${i}`,`R${i+1}`,5],[`R${i}`,`L${i+1}`,5],[`BL${i}`,`BR${i+1}`,5],[`BR${i}`,`BL${i+1}`,5]);
