    ["S690 CHS48.3x3.2","S690 CHS60.3x4","S690 CHS76.1x4","S690 CHS88.9x5","S690 CHS114.3x5","S690 CHS139.7x5","S690 CHS139.7x6.3"],
    ["S690 CHS76.1x4","S690 CHS88.9x5","S690 CHS114.3x5","S690 CHS139.7x5","S690 CHS139.7x6.3","S690 CHS168.3x5"],
    ["S690 CHS42.4x3.2","S690 CHS48.3x3.2","S690 CHS60.3x3.2","S690 CHS60.3x4","S690 CHS76.1x4","S690 CHS88.9x5"],
    ["S690 CHS42.4x3.2","S690 CHS48.3x3.2","S690 CHS60.3x3.2","S690 CHS60.3x4","S690 CHS76.1x4","S690 CHS88.9x5"],
    ["S690 CHS42.4x3.2","S690 CHS48.3x3.2","S690 CHS60.3x3.2","S690 CHS60.3x4","S690 CHS76.1x4","S690 CHS88.9x5"],
    ["S690 CHS42.4x3.2","S690 CHS48.3x3.2","S690 CHS60.3x3.2","S690 CHS60.3x4","S690 CHS76.1x4","S690 CHS88.9x5"]
  ];
  const si = md.map(d => [6,3,3,3,3,3,3][d[2]]);
  const build = () => ({
    note: "Below-deck space truss S690 CHS, full 3D X-braced with cross-plane diagonals for rigidity",
    nodes: nodes.map(n=>({...n})),
    members: md.map((d,i)=>[d[0],d[1],S[d[2]][si[i]]])
  });
  let bestD=null, bestM=Infinity;
  for (let it=0; it<250; it++) {
    const d=build(), r=analyse(d);
    if (r.error) {
      let ch=false;
      for (let i=0;i<si.length;i++) if (si[i]<S[md[i][2]].length-1) {si[i]++;ch=true;}
      if (!ch) break;
      continue;
    }
    if (r.ok && r.mass<bestM) { bestD=JSON.parse(JSON.stringify(d)); bestM=r.mass; }
    const m=r.members||[];
    if (r.ok) {
      let ch=false;
      for (const t of [0.3,0.5,0.65]) {
        for (let i=0;i<Math.min(m.length,si.length);i++) if (m[i] && m[i].util<t && si[i]>0) {si[i]--;ch=true;}
        if (ch) break;
      }
      if (!ch) break;
    } else {
      let ch=false;
      for (const t of [0.9,0.7,0.5]) {
        for (let i=0;i<Math.min(m.length,si.length);i++) if (m[i] && m[i].util>t && si[i]<S[md[i][2]].length-1) {si[i]++;ch=true;}
