      }
      if (!ch) {
        for (let i=0;i<si.length;i++) if (si[i]<S[md[i][2]].length-1) {si[i]++;ch=true;}
      }
      if (!ch) break;
    }
  }
  return bestD||build();
}

function design(site, analyse) {
  const xs = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const yBottom = -5.42;
  const nodes = [];
  const xyz = Object.create(null);

  for (let i = 0; i < 10; i++) {
    xyz["L" + i] = [xs[i], 0, -2.65];
    xyz["R" + i] = [xs[i], 0, 2.65];
    nodes.push({ id: "BL" + i, x: xs[i], y: yBottom, z: -2.65 });
    nodes.push({ id: "BR" + i, x: xs[i], y: yBottom, z: 2.65 });
    xyz["BL" + i] = [xs[i], yBottom, -2.65];
    xyz["BR" + i] = [xs[i], yBottom, 2.65];
  }

  const sectionData = [
    ["CHS33.7x2.6", 2.54], ["CHS42.4x3.2", 3.94],
    ["CHS48.3x3.2", 4.53], ["CHS60.3x3.2", 5.74],
    ["CHS60.3x4", 7.07], ["CHS76.1x3.2", 7.33],
    ["CHS76.1x4", 9.06], ["CHS88.9x4", 10.67],
    ["CHS88.9x5", 13.18], ["CHS114.3x4", 13.86],
    ["CHS114.3x5", 17.17], ["CHS139.7x5", 21.16],
    ["CHS168.3x5", 25.65], ["CHS139.7x6.3", 26.4],
    ["CHS168.3x6.3", 32.06], ["CHS193.7x6.3", 37.09],
    ["CHS193.7x8", 46.67], ["CHS219.1x8", 53.06],
    ["CHS244.5x8", 59.44], ["CHS273x10", 82.62],
    ["CHS323.9x10", 98.61], ["CHS355.6x12.5", 134.74],
    ["CHS406.4x12.5", 154.68], ["CHS457x16", 221.67]
  ];
  const sections = sectionData.map(x => x[0]);
  const areas = sectionData.map(x => x[1]);

  const starts = {
    top: 21, bottom: 20, post: 18, web: 19,
    ctop: 16, cbot: 16, pTop: 14, pBot: 14, xsec: 17
  };
  const members = [];

  function add(a, b, role) {
    const p = xyz[a], q = xyz[b];
    const dx = p[0] - q[0], dy = p[1] - q[1], dz = p[2] - q[2];
    members.push({
      a: a, b: b, role: role, mat: "S460", idx: starts[role],
      len: Math.sqrt(dx * dx + dy * dy + dz * dz)
    });
  }

  for (let i = 0; i < 9; i++) {
    add("L" + i, "L" + (i + 1), "top");
    add("R" + i, "R" + (i + 1), "top");
    add("BL" + i, "BL" + (i + 1), "bottom");
    add("BR" + i, "BR" + (i + 1), "bottom");
  }

  for (let i = 0; i < 10; i++) {
    add("L" + i, "BL" + i, "post");
    add("R" + i, "BR" + i, "post");
    add("L" + i, "R" + i, "ctop");
    add("BL" + i, "BR" + i, "cbot");
    add("L" + i, "BR" + i, "xsec");
  }

  for (const side of ["L", "R"]) {
    const low = side === "L" ? "BL" : "BR";
    for (let i = 0; i < 9; i++) {
      if (i < 4) {
        add(side + i, low + (i + 1), "web");
      } else if (i === 4) {
        add(side + i, low + (i + 1), "web");
        add(low + i, side + (i + 1), "web");
      } else {
        add(low + i, side + (i + 1), "web");
      }
    }
  }

  for (let i = 0; i < 9; i++) {
    add("L" + i, "R" + (i + 1), "pTop");
    add("BL" + i, "BR" + (i + 1), "pBot");
  }

  const note =
    "Pinned 5.42 m-deep twin side trusses use cross-frames and top/bottom plan bracing; the analyser trims sections and tests lighter pinned alloys.";

  function emit() {
    return {
      note: note,
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z })),
      members: members.map(m => ({
        a: m.a, b: m.b, spec: m.mat + " " + sections[m.idx]
      }))
    };
  }

  let calls = 0;
  const MAX_CALLS = 380;

  function run() {
    if (calls >= MAX_CALLS) return null;
    calls++;
    try {
      return analyse(emit());
    } catch (e) {
      return { error: String(e) };
    }
  }

  function num(v) {
    if (typeof v === "number" && isFinite(v)) return v;
    if (typeof v === "string" && v.trim() !== "") {
      const n = Number(v);
      if (isFinite(n)) return n;
    }
    return null;
  }

  function passes(r) {
    if (!r || r.error || r.ok !== true) return false;

    let u = num(r.maxUtil);
    for (const c of (r.cases || [])) {
      const v = num(c.maxUtil);
      if (v !== null) u = u === null ? v : Math.max(u, v);
    }
    for (const m of (r.members || [])) {
      const v = num(m.util);
      if (v !== null) u = u === null ? v : Math.max(u, v);
    }
    if (u !== null) {
      if (u > 10) u /= 100;
      if (u > 0.72) return false;
    }

    let cr = num(r.alphaCrMin);
    if (cr === null) cr = num(r.alphaCr);
    if (cr !== null && cr < 7.5) return false;

    const sag = num(r.sag), sagLimit = num(r.sagLimit);
    if (sag !== null && sagLimit !== null && sagLimit > 0 &&
        Math.abs(sag) > 0.80 * sagLimit) return false;

    const sway = num(r.sway), swayLimit = num(r.swayLimit);
    if (sway !== null && swayLimit !== null && swayLimit > 0 &&
        Math.abs(sway) > 0.80 * swayLimit) return false;

    const freq = num(r.frequency);
    if (freq !== null && freq < 2.48) return false;

    let fatigue = num(r.fatigueWorst);
    if (fatigue === null && r.fatigueWorst && typeof r.fatigueWorst === "object") {
      const f = r.fatigueWorst;
      fatigue = num(f.util);
      if (fatigue === null) fatigue = num(f.ratio);
      if (fatigue === null) fatigue = num(f.stressRange);
      if (fatigue === null) fatigue = num(f.value);
    }
    if (fatigue !== null) {
      if (fatigue <= 1.5 && fatigue > 0.72) return false;
      if (fatigue > 10 && fatigue > 65) return false;
    }

    if (r.robustness === false || r.robustness === 0) return false;
    if (r.robustness && typeof r.robustness === "object" &&
        (r.robustness.ok === false || r.robustness.pass === false)) return false;

    return true;
  }

  let current = run();
  if (!passes(current)) return emit();

  function lighter(r) {
    const a = num(r && r.mass);
    const b = num(current && current.mass);
    return a !== null && b !== null && a < b - 1e-6;
  }

  const roleOrder = [
    "top", "bottom", "web", "post", "ctop",
    "cbot", "xsec", "pTop", "pBot"
  ];

  for (const role of roleOrder) {
    while (calls < 140) {
      const group = members.filter(m => m.role === role);
      if (group.length === 0) break;
      const k = group[0].idx;
      if (k <= 0 || group.some(m => m.idx !== k)) break;

      for (const m of group) m.idx = k - 1;
      const r = run();
      if (passes(r) && lighter(r)) {
        current = r;
      } else {
        for (const m of group) m.idx = k;
        break;
      }
    }
  }

  const SECTION_LIMIT = 260;
  for (let sweep = 0; sweep < 3 && calls < SECTION_LIMIT; sweep++) {
    const order = members.map((m, i) => i);
    order.sort((a, b) => {
      const ma = members[a], mb = members[b];
      const da = ma.idx > 0 ? areas[ma.idx] - areas[ma.idx - 1] : 0;
      const db = mb.idx > 0 ? areas[mb.idx] - areas[mb.idx - 1] : 0;
      return db * mb.len - da * ma.len;
    });

    let changed = false;
    for (const j of order) {
      const m = members[j];
      while (m.idx > 0 && calls < SECTION_LIMIT) {
        const old = m.idx;
        m.idx = old - 1;
        const r = run();
        if (passes(r) && lighter(r)) {
          current = r;
          changed = true;
        } else {
          m.idx = old;
          break;
        }
      }
      if (calls >= SECTION_LIMIT) break;
    }
    if (!changed) break;
  }

  const density = { S460: 7850, AL7075: 2810, AL6082: 2700 };
  const eligibleRoles = ["ctop", "cbot", "pTop", "pBot", "xsec"];
  const eligible = members
    .filter(m => eligibleRoles.indexOf(m.role) >= 0)
    .sort((a, b) =>
      density[b.mat] * areas[b.idx] * b.len -
      density[a.mat] * areas[a.idx] * a.len
    );

  function firstAreaAtLeast(a) {
    for (let i = 0; i < areas.length; i++) {
      if (areas[i] >= a) return i;
    }
    return -1;
  }

  for (const m of eligible) {
    if (calls >= MAX_CALLS) break;
    const k = m.idx;
    const oldMat = m.mat;
    const oldIdx = m.idx;
    const baseMass = density[oldMat] * areas[oldIdx];
    const candidates = [];
    const seen = Object.create(null);

    function candidate(mat, idx) {
      if (idx < 0 || idx >= sections.length) return;
      const key = mat + ":" + idx;
      const proxy = density[mat] * areas[idx];
      if (!seen[key] && proxy < baseMass) {
        seen[key] = true;
        candidates.push({ mat: mat, idx: idx, proxy: proxy });
      }
    }

    candidate("AL7075", k - 1);
    candidate("AL7075", k);
    candidate("AL7075", k + 1);

    for (const factor of [1.45, 1.65, 1.85]) {
      const j = firstAreaAtLeast(areas[k] * factor);
      if (j >= 0) candidate("AL6082", j);
    }

    candidates.sort((a, b) => a.proxy - b.proxy);
    let tried = 0;
    for (const c of candidates) {
      if (calls >= MAX_CALLS || tried >= 3) break;
      tried++;
      m.mat = c.mat;
      m.idx = c.idx;
      const r = run();
      if (passes(r) && lighter(r)) {
        current = r;
        break;
      }
      m.mat = oldMat;
      m.idx = oldIdx;
    }
  }

  return emit();
}

function design(site, analyse) {
