  const starts = {
    top: 21, bottom: 20, post: 18, web: 19,
    ctop: 16, cbot: 16, pTop: 19, pBot: 17, xsec: 17
  };

  function makeMember(a, b, role, idx, meta) {
    const p = xyz[a], q = xyz[b];
    const dx = p[0] - q[0], dy = p[1] - q[1], dz = p[2] - q[2];
    const m = {
      a: a, b: b, role: role, idx: idx, mat: "S460",
      len: Math.sqrt(dx * dx + dy * dy + dz * dz)
    };
    if (meta) Object.assign(m, meta);
    return m;
  }

  let members = [];
  function add(a, b, role, meta) {
    members.push(makeMember(a, b, role, starts[role], meta));
  }

  for (let i = 0; i < 9; i++) {
