    }

    function groupTag(m) {
      return m.panel !== undefined
        ? m.role + "|p" + m.panel
        : m.role + "|s" + m.station;
    }

    function groupTrim(end) {
      const blocked = Object.create(null);

      while (calls < end) {
        const byTag = Object.create(null);

        for (const m of best) {
          const tag = groupTag(m);
          if (!byTag[tag]) byTag[tag] = [];
          byTag[tag].push(m);
