        const options = [];
        for (const tag of Object.keys(byTag)) {
          const group = byTag[tag];
          if (group.length < 2) continue;
          if (!group.some(m => m.idx > 0)) continue;

          const signature = tag + "|" +
            group.map(m => m.idx).join(",");
          if (blocked[signature]) continue;

          let saving = 0;
          for (const m of group) saving += stepSaving(m);
          options.push({
            tag: tag,
            signature: signature,
            saving: saving
          });
        }

        if (options.length === 0) break;
        options.sort((a, b) => b.saving - a.saving);

        const choice = options[0];
        const candidate = cloneList(best);
        for (const m of candidate) {
          if (groupTag(m) === choice.tag && m.idx > 0) m.idx--;
        }

        const r = run(candidate);
        if (acceptable(r) &&
            mass(r) !== null &&
            mass(bestR) !== null &&
            mass(r) < mass(bestR) - 1e-6) {
          best = candidate;
          bestR = r;
        } else {
          blocked[choice.signature] = true;
        }
      }
    }

    function deletionTrim(end) {
      const eligible = {
        post: true,
        xsec: true,
        ctop: true,
        cbot: true
      };
      const entries = [];

      for (const m of best) {
        if (!eligible[m.role]) continue;
        const u = reportUtil(m, bestR);
        if (u === null || u > 0.10) continue;

        entries.push({
          key: memberKey(m),
          priority: stepSaving(m) / (0.02 + u)
        });
      }

      entries.sort((a, b) => b.priority - a.priority);

      for (const entry of entries) {
        if (calls >= end) break;
        const candidate = best.filter(m => memberKey(m) !== entry.key);
        if (candidate.length < best.length) {
          submit(cloneList(candidate), false);
        }
      }
    }

    sectionTrim(Math.min(MAX_CALLS, calls + 300));
    groupTrim(Math.min(MAX_CALLS, calls + 18));
    aluminumTrim(Math.min(MAX_CALLS, calls + 18), 18);
    deletionTrim(Math.min(MAX_CALLS, calls + 12));
    sectionTrim(MAX_CALLS);
  }

  return emit(best);
}

