      if (limit === null) limit = num(f.allowed);
      if (limit === null) limit = num(f.allowable);
      const stress = num(f.stressRange);
      if (stress !== null) return stress / (limit || 90);
      const value = num(f.value);
      if (value !== null) {
        if (limit !== null && value > 1.5) return value / limit;
        return value > 10 ? value / (limit || 90) : value;
      }
