      for (const old of order) {
        if (calls >= end) break;
        const k = key(old);

        while (calls < end) {
          const i = best.members.findIndex(m => key(m) === k);
          if (i < 0 || best.members[i].idx <= 0) break;

          const candidate = cloneState(best);
          candidate.members[i].idx--;
          const r = run(candidate);
          if (good(r) && mass(r) !== null && mass(bestR) !== null &&
              mass(r) < mass(bestR) - 1e-6) {
            best = candidate;
            bestR = r;
            changed = true;
          } else {
            break;
          }
        }
      }
      if (!changed) break;
    }
  }

  trimSections(Math.min(MAX_CALLS, calls + 220));

  const allowedAluminiumRoles = {
    post: true, web: true, ctop: true, cbot: true,
    xsec: true, pTop: true, pBot: true
  };
  const aluminiumCandidates = [];
  for (const m of best.members) {
    if (!allowedAluminiumRoles[m.role] || m.mat === "AL7075") continue;
    const u = reportUtil(m, bestR);
    if (u === null || u > 0.25) continue;
    const saving = m.len * areas[m.idx] * 1e-4 * (7850 - 2810);
    aluminiumCandidates.push({
      key: key(m),
      saving: saving,
      priority: saving / (0.10 + u)
    });
  }
  aluminiumCandidates.sort((a, b) => b.priority - a.priority);

  const aluminiumEnd = Math.min(MAX_CALLS, calls + 60);
  for (const entry of aluminiumCandidates) {
    if (calls >= aluminiumEnd) break;
    const i = best.members.findIndex(m => key(m) === entry.key);
    if (i < 0 || best.members[i].mat === "AL7075") continue;

    const candidate = cloneState(best);
    candidate.members[i].mat = "AL7075";
    const r = run(candidate);
    if (good(r) && mass(r) !== null && mass(bestR) !== null &&
        mass(r) < mass(bestR) - 1e-6) {
      best = candidate;
      bestR = r;
    }
  }

  trimSections(MAX_CALLS);
  return emit(best);
}

