  const note =
    "Pinned Pratt side trusses retain full 3-D bracing; sections are report-sized and trimmed adaptively, with aluminium tried only where fatigue and stability margins permit.";

  const MAX_CALLS = 398;
  let calls = 0;

  function num(v) {
    if (typeof v === "number" && isFinite(v)) return v;
    if (typeof v !== "string") return null;
    const match = v.trim().replace(/,/g, "").match(
      /[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/
