  function ratio(v) {
    let x = num(v);
    if (x !== null && x > 10) x /= 100;
    return x;
  }

  function memberKey(m) {
    return m.a + "|" + m.b;
  }

  function memberTag(m) {
    return m.panel !== undefined
      ? m.role + "|p" + m.panel
      : m.role + "|s" + m.station;
  }

  function lengthBetween(p, q) {
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
    const dz = p[2] - q[2];
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  function build(depth) {
    const nodes = [];
    const xyz = Object.create(null);
    const members = [];

    for (let i = 0; i < 10; i++) {
      xyz["L" + i] = [xs[i], 0, -2.65];
      xyz["R" + i] = [xs[i], 0, 2.65];

      const bl = "BL" + i;
      const br = "BR" + i;
      nodes.push({ id: bl, x: xs[i], y: depth, z: -2.65 });
      nodes.push({ id: br, x: xs[i], y: depth, z: 2.65 });
      xyz[bl] = [xs[i], depth, -2.65];
      xyz[br] = [xs[i], depth, 2.65];
    }

    function add(a, b, role, meta) {
      const m = {
        a: a,
        b: b,
        role: role,
        idx: starts[role],
        mat: "S460",
        len: lengthBetween(xyz[a], xyz[b])
      };
      if (meta) Object.assign(m, meta);
      members.push(m);
    }

    for (let i = 0; i < 9; i++) {
      add("L" + i, "L" + (i + 1), "top", { panel: i });
      add("R" + i, "R" + (i + 1), "top", { panel: i });
      add("BL" + i, "BL" + (i + 1), "bottom", { panel: i });
      add("BR" + i, "BR" + (i + 1), "bottom", { panel: i });
    }

    for (let i = 0; i < 10; i++) {
      add("L" + i, "BL" + i, "post", { station: i });
      add("R" + i, "BR" + i, "post", { station: i });
      add("L" + i, "R" + i, "ctop", { station: i });
      add("BL" + i, "BR" + i, "cbot", { station: i });
      add("L" + i, "BR" + i, "xsec", { station: i });
    }

    for (const side of ["L", "R"]) {
      const low = side === "L" ? "BL" : "BR";

      for (let i = 0; i < 9; i++) {
        if (i < 4) {
          add(side + i, low + (i + 1), "web",
              { side: side, panel: i });
        } else if (i === 4) {
          add(side + i, low + (i + 1), "web",
              { side: side, panel: i });
          add(low + i, side + (i + 1), "web",
              { side: side, panel: i, extra: true });
        } else {
          add(low + i, side + (i + 1), "web",
              { side: side, panel: i });
        }
      }
    }

    for (let i = 0; i < 9; i++) {
      add("L" + i, "R" + (i + 1), "pTop", { panel: i });
      add("BL" + i, "BR" + (i + 1), "pBot", { panel: i });
