    let trialR = seedR;

    for (let step = 0; step < 6 && calls < MAX_CALLS; step++) {
      const next = cloneState(trial);
      let changed = false;

      for (const m of next.members) {
        const u = reportUtil(m, trialR);
        if (u === null) continue;

        const mode = reportMode(m, trialR);
        const limit = mode.includes("fatigue") ? 0.76 :
          ((mode.includes("buckl") || mode.includes("compress")) ? 0.69 : 0.71);
        const key = memberKey(m);
        const ceiling = referenceIndex[key];

        if (u > limit && m.idx < ceiling) {
          m.idx = Math.min(ceiling, m.idx + (u > 1 ? 2 : 1));
          changed = true;
        }
      }

      if (!changed) {
        for (const m of next.members) {
          const ceiling = referenceIndex[memberKey(m)];
          if (m.idx < ceiling) {
            m.idx++;
            changed = true;
          }
        }
      }

      if (!changed) break;

      trialR = run(next);
      trial = next;
      if (consider(trial, trialR)) break;
    }

    for (const fraction of [0.25, 0.50, 0.75]) {
      if (calls >= MAX_CALLS) break;
      const blend = cloneState(seed);

      for (const m of blend.members) {
        const key = memberKey(m);
        const ceiling = referenceIndex[key];
        m.idx = Math.min(
          ceiling,
          m.idx + Math.round((ceiling - m.idx) * fraction)
        );
      }

