    let blocked = new Set();
    let oldSignature = "";

    while (calls < end && accepted < maxAccepted) {
      const signature = best.members
        .map(m => memberKey(m) + ":" + m.idx + ":" + m.mat)
        .join(";");

      if (signature !== oldSignature) {
        blocked.clear();
        oldSignature = signature;
      }

      const options = [];
      for (const m of best.members) {
        if (m.idx <= 0) continue;
        const token = memberKey(m) + "@" + m.idx;
        if (blocked.has(token)) continue;
        options.push({ key: memberKey(m), token: token, saving: stepSaving(m) });
      }
      options.sort((a, b) => b.saving - a.saving);

      if (options.length === 0) break;

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].idx <= 0) {
          blocked.add(option.token);
          continue;
        }

        const candidate = cloneState(best);
        candidate.members[i].idx--;
        const r = run(candidate);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          blocked.clear();
          oldSignature = "";
          break;
        }

        blocked.add(option.token);
      }

      if (!changed) break;
    }
  }

  function trimGroups(end, maxAccepted) {
    let accepted = 0;
    const blocked = new Set();

    while (calls < end && accepted < maxAccepted) {
      const groups = Object.create(null);

      for (const m of best.members) {
        const tag = memberTag(m);
        if (!groups[tag]) groups[tag] = [];
        groups[tag].push(m);
      }

      const options = [];
      for (const tag of Object.keys(groups)) {
        const group = groups[tag];
        const reducible = group.filter(m => m.idx > 0);
        if (reducible.length === 0) continue;

        const signature = tag + "|" +
          group.map(m => m.idx).join(",");
        if (blocked.has(signature)) continue;

        let saving = 0;
        for (const m of reducible) saving += stepSaving(m);
        options.push({ tag: tag, signature: signature, saving: saving });
      }

      options.sort((a, b) => b.saving - a.saving);
      if (options.length === 0) break;

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const candidate = cloneState(best);
        for (const m of candidate.members) {
          if (memberTag(m) === option.tag && m.idx > 0) m.idx--;
        }

        const r = run(candidate);
        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          blocked.clear();
          break;
        }

        blocked.add(option.signature);
      }

      if (!changed) break;
    }
  }

  function tryAluminium(end, maxAccepted) {
    let accepted = 0;
    const tested = new Set();

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (m.mat === "AL7075") continue;
        const key = memberKey(m);
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        if (u === null) continue;

        const mode = reportMode(m, bestR);
        const limit = mode.includes("fatigue") ? 0.22 : 0.29;
        if (u > limit) continue;

        const saving = fullMemberMass(m) * (1 - 2810 / density(m));
        options.push({
          key: key,
          saving: saving,
          priority: saving / (0.12 + u)
        });
      }

      options.sort((a, b) => b.priority - a.priority);
      if (options.length === 0) break;

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].mat === "AL7075") {
          tested.add(option.key);
          continue;
        }

        const candidate = cloneState(best);
        candidate.members[i].mat = "AL7075";
        const r = run(candidate);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          tested.clear();
          break;
        }

        tested.add(option.key);
      }

      if (!changed) break;
    }
  }

  function tryS690(end, maxAccepted) {
    let accepted = 0;
    const tested = new Set();

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (m.mat !== "S460" || m.idx <= 0) continue;

        const key = memberKey(m);
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        if (u === null || u < 0.24 || u > 0.68) continue;
        if (reportMode(m, bestR).includes("fatigue")) continue;

        options.push({
          key: key,
          saving: stepSaving(m)
        });
      }

      options.sort((a, b) => b.saving - a.saving);
      if (options.length === 0) break;

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].idx <= 0) {
          tested.add(option.key);
          continue;
        }

        const candidate = cloneState(best);
        candidate.members[i].mat = "S690";
        candidate.members[i].idx--;
        const r = run(candidate);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          tested.clear();
          break;
        }

        tested.add(option.key);
      }

      if (!changed) break;
    }
  }

  function tryRemovals(end, maxAccepted) {
    const eligible = {
      post: true, ctop: true, cbot: true, xsec: true,
      pTop: true, pBot: true
    };
    let accepted = 0;
    const tested = new Set();

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (!eligible[m.role] && !(m.role === "web" && m.extra)) continue;

        const key = memberKey(m);
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        if (u === null) continue;
        if (u > (m.extra ? 0.42 : 0.18)) continue;

        const saving = fullMemberMass(m);
        options.push({
          key: key,
          saving: saving / (0.04 + u)
        });
      }

      options.sort((a, b) => b.saving - a.saving);
      if (options.length === 0) break;

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const candidate = cloneState(best);
        candidate.members = candidate.members.filter(
          m => memberKey(m) !== option.key
        );

        const r = run(candidate);
        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          tested.clear();
          break;
        }

        tested.add(option.key);
      }

      if (!changed) break;
    }
  }

  function tryDepths(end) {
    const depths = [-5.20, -4.95, -4.70, -5.35];

    for (const d of depths) {
      if (calls >= end) break;
      if (Math.abs(best.depth - d) < 1e-6) continue;

      const candidate = cloneState(best);
      setDepth(candidate, d);
      consider(candidate, run(candidate));
    }
  }

  trimSections(Math.min(MAX_CALLS, calls + 180), 90);
  tryAluminium(Math.min(MAX_CALLS, calls + 50), 40);
  tryDepths(Math.min(MAX_CALLS, calls + 4));
  trimSections(Math.min(MAX_CALLS, calls + 68), 48);
  trimGroups(Math.min(MAX_CALLS, calls + 24), 16);
  tryS690(Math.min(MAX_CALLS, calls + 12), 8);
  tryRemovals(Math.min(MAX_CALLS, calls + 24), 12);

  return emit(best);
}

