    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
    "CHS244.5x8", "CHS273x10", "CHS323.9x10",
    "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];

  const areas = [
    2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67,
    13.18, 13.86, 17.17, 21.16, 25.65, 26.4, 32.06,
    37.09, 46.67, 53.06, 59.44, 82.62, 98.61, 134.74,
    154.68, 221.67
  ];

  const starts = {
    top: 23, bottom: 22, post: 20, web: 21,
    ctop: 18, cbot: 18, xsec: 19, pTop: 21, pBot: 19
  };

  const seedIdx = {
    top: 19, bottom: 19, post: 18, web: 18,
    ctop: 17, cbot: 16, xsec: 17, pTop: 17, pBot: 16
  };

  const note =
    "Keeps the proven pinned twin-Pratt 3-D load path, then uses margin-checked analysis to trim sections, test light-alloy and S690 members, and remove only verified redundancies.";

  const MAX_CALLS = 399;
  let calls = 0;

  function lengthBetween(p, q) {
    const dx = p[0] - q[0];
    const dy = p[1] - q[1];
