    }

    return true;
  }

  function mass(r) {
    return num(r && r.mass);
  }

  function memberKey(m) {
    return m.a + "|" + m.b;
  }

  function density(m) {
    if (m.mat === "AL7075") return 2810;
    if (m.mat === "SS316") return 8000;
    if (m.mat === "GL28") return 420;
    return 7850;
  }

  function fullMemberMass(m) {
    return areas[m.idx] * 1e-4 * m.len * density(m);
  }

  function stepSaving(m) {
    if (!m || m.idx <= 0) return 0;
    return Math.max(
      0,
      (areas[m.idx] - areas[m.idx - 1]) *
        1e-4 * m.len * density(m)
    );
  }

  function findReport(m, r) {
    const reports = Array.isArray(r && r.members) ? r.members : [];
    const forward = m.a + "-" + m.b;
    const reverse = m.b + "-" + m.a;

    for (const q of reports) {
      if (!q) continue;
      let id = q.id;
      if (id === undefined) id = q.member;
      if (id !== undefined &&
          (String(id) === forward || String(id) === reverse)) {
        return q;
      }
      if (q.a !== undefined && q.b !== undefined &&
          ((String(q.a) === m.a && String(q.b) === m.b) ||
           (String(q.a) === m.b && String(q.b) === m.a))) {
        return q;
      }
    }
    return null;
  }

  function reportUtil(m, r) {
    const q = findReport(m, r);
    if (!q) return null;
    return ratio(q.util !== undefined ? q.util : q.utilization);
  }

  function reportMode(m, r) {
    const q = findReport(m, r);
    return String(q && q.mode || "").toLowerCase();
  }

  let best = build(-5.42);
  let bestR = run(best);
  if (!enginePass(bestR)) return emit(best);

  function consider(candidate, r) {
    if (!safe(r)) return false;

    const newMass = mass(r);
    const oldMass = mass(bestR);
    if (newMass === null ||
        (oldMass !== null && newMass >= oldMass - 0.01)) {
      return false;
    }

    best = cloneState(candidate);
    bestR = r;
    return true;
  }

