  const target = cloneState(reference);
  for (const m of target.members) {
    m.idx = Math.min(m.idx, seedIdx[m.role]);
  }

  let seedAccepted = consider(target, run(target));
  if (!seedAccepted) {
    for (const fraction of [0.50, 0.75]) {
      if (calls >= MAX_CALLS) break;
      const blend = cloneState(reference);

      for (const m of blend.members) {
        const start = starts[m.role];
        const end = Math.min(start, seedIdx[m.role]);
        m.idx = Math.max(end, start - Math.round((start - end) * fraction));
      }
      consider(blend, run(blend));
    }
  }

  function trimSections(end) {
    const blocked = new Set();

    while (calls < end) {
      const options = [];

      for (const m of best.members) {
        if (m.idx <= 0) continue;
        const token = memberKey(m) + "@" + m.idx;
        if (blocked.has(token)) continue;
        options.push({
          key: memberKey(m),
          idx: m.idx,
          token: token,
          saving: stepSaving(m)
        });
      }

      if (options.length === 0) break;
      options.sort((a, b) => b.saving - a.saving);

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].idx !== option.idx) continue;

        const candidate = cloneState(best);
        candidate.members[i].idx--;
        const r = run(candidate);

        if (consider(candidate, r)) {
          changed = true;
          break;
        }
        blocked.add(option.token);
      }

      if (!changed) break;
    }
  }

  function tryAluminium(end, maxAccepted) {
    const tested = new Set();
    let accepted = 0;

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (m.mat === "AL7075") continue;

        const key = memberKey(m);
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        if (u === null || u > 0.20) continue;

        const mode = reportMode(m, bestR);
        if ((mode.includes("buckl") || mode.includes("compress")) &&
            u > 0.12) {
          continue;
        }

        const saving = fullMemberMass(m) * (1 - 2810 / 7850);
        options.push({
          key: key,
          priority: saving / (0.08 + u)
        });
      }

      if (options.length === 0) break;
      options.sort((a, b) => b.priority - a.priority);

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].mat === "AL7075") {
          tested.add(option.key);
          continue;
        }

        const candidate = cloneState(best);
        candidate.members[i].mat = "AL7075";
        const r = run(candidate);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          break;
        }
        tested.add(option.key);
      }

      if (!changed) break;
    }
  }

  function tryDepths(end) {
    for (const depth of [-5.62, -5.50, -5.25, -4.95]) {
      if (calls >= end) break;
      if (Math.abs(best.depth - depth) < 1e-6) continue;

      const candidate = cloneState(best);
      setDepth(candidate, depth);
      consider(candidate, run(candidate));
    }
  }

  function tryS690(end, maxAccepted) {
    const tested = new Set();
    let accepted = 0;

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (m.mat !== "S460" || m.idx <= 0) continue;

        const key = memberKey(m) + "@" + m.idx;
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        const mode = reportMode(m, bestR);
        if (u === null || u < 0.28 || u > 0.78 ||
            mode.includes("fatigue")) {
          continue;
        }

        options.push({
          key: memberKey(m),
          idx: m.idx,
          token: key,
          saving: stepSaving(m)
        });
      }

      if (options.length === 0) break;
      options.sort((a, b) => b.saving - a.saving);

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const i = best.members.findIndex(
          m => memberKey(m) === option.key
        );
        if (i < 0 || best.members[i].idx !== option.idx ||
            best.members[i].mat !== "S460") {
          tested.add(option.token);
          continue;
        }

        const candidate = cloneState(best);
        candidate.members[i].mat = "S690";
        candidate.members[i].idx--;
        const r = run(candidate);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          break;
        }
        tested.add(option.token);
      }

      if (!changed) break;
    }
  }

  function tryRemovals(end, maxAccepted) {
    const eligible = {
      post: true, cbot: true, xsec: true,
      pTop: true, pBot: true
    };
    const tested = new Set();
    let accepted = 0;

    while (calls < end && accepted < maxAccepted) {
      const options = [];

      for (const m of best.members) {
        if (!eligible[m.role] && !(m.role === "web" && m.extra)) continue;

        const key = memberKey(m);
        if (tested.has(key)) continue;

        const u = reportUtil(m, bestR);
        if (u === null || u > (m.extra ? 0.35 : 0.20)) continue;

        options.push({
          key: key,
          priority: fullMemberMass(m) / (0.05 + u)
        });
      }

      if (options.length === 0) break;
      options.sort((a, b) => b.priority - a.priority);

      let changed = false;
      for (const option of options) {
        if (calls >= end) break;

        const candidate = cloneState(best);
        candidate.members = candidate.members.filter(
          m => memberKey(m) !== option.key
        );

        const r = run(candidate);
        tested.add(option.key);

        if (consider(candidate, r)) {
          accepted++;
          changed = true;
          break;
        }
      }

      if (!changed) break;
    }
  }

  trimSections(Math.min(MAX_CALLS, calls + 225));
  tryAluminium(Math.min(MAX_CALLS, calls + 55), 45);
  tryDepths(Math.min(MAX_CALLS, calls + 4));
  trimSections(Math.min(MAX_CALLS, calls + 55));
  tryS690(Math.min(MAX_CALLS, calls + 25), 20);
  tryRemovals(Math.min(MAX_CALLS, calls + 20), 12);
  trimSections(MAX_CALLS);

  return emit(best);
}

