    for (let i = 0; i < 9; i++) add('L' + i, 'L' + (i + 1), 'topChord', i, 'L');
    for (let i = 0; i < 9; i++) add('R' + i, 'R' + (i + 1), 'topChord', i, 'R');
    for (let j = 0; j < 8; j++) add('C' + j, 'C' + (j + 1), 'bottomChord', j, '');
    for (let j = 0; j < 9; j++) {
      add('C' + j, 'L' + j, 'diagonal', j, 'L');
      add('C' + j, 'R' + j, 'diagonal', j, 'R');
      add('C' + j, 'L' + (j + 1), 'diagonal', j, 'L');
      add('C' + j, 'R' + (j + 1), 'diagonal', j, 'R');
    }
    for (let i = 0; i < 10; i++) add('L' + i, 'R' + i, 'topCross', i, '');
    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) add('L' + i, 'R' + (i + 1), 'topLat', i, '');
      else add('R' + i, 'L' + (i + 1), 'topLat', i, '');
    }
    return { nodes, mdefs };
  }

  function fatigueMinBox(H, md) {
    const { type, idx, side } = md;
    const half = 4.144 / 2;
    const Ld = Math.sqrt(half * half + H * H);
    if (type === 'topChord' || type === 'bottomChord') {
      let x1, x2;
      if (type === 'topChord') { x1 = xs[idx]; x2 = xs[idx + 1]; }
      else { x1 = mid[idx]; x2 = mid[idx + 1]; }
      const xm = clamp(L / 2, Math.min(x1, x2), Math.max(x1, x2));
      const M = P_live * xm * (L - xm) / L;
      const force = M / (2 * H);
      return sf * force * 1000 / df * 1e4;
    }
    if (type === 'diagonal') {
      const x = mid[idx];
      const Vmax = P_live * Math.max(x / L, 1 - x / L);
      const frac = side === 'L' ? fracL : fracR;
      const N = frac * Vmax * (Ld / H);
      return sf * N * 1000 / df * 1e4;
    }
    if (type === 'topCross' || type === 'bottomCross') {
      const N = P_live * 0.59 / 5.3;
      return Math.max(sf * N * 1000 / df * 1e4, 10);
    }
    if (type === 'topLat' || type === 'bottomLat') {
      const N = 0.2 * P_live;
      return Math.max(sf * N * 1000 / df * 1e4, 9);
    }
    if (type === 'transBrace') return 9;
    return 5;
  }

  function fatigueMinCentral(H, md) {
    const { type, idx, side } = md;
    const half = 4.144 / 2;
    const Ld = Math.sqrt(half * half + H * H + 2.65 * 2.65);
    if (type === 'topChord') {
      const x1 = xs[idx], x2 = xs[idx + 1];
      const xm = clamp(L / 2, Math.min(x1, x2), Math.max(x1, x2));
      const M = P_live * xm * (L - xm) / L;
      const frac = side === 'L' ? fracL : fracR;
      const force = M / H * frac;
      return sf * force * 1000 / df * 1e4;
    }
    if (type === 'bottomChord') {
      const x1 = mid[idx], x2 = mid[idx + 1];
      const xm = clamp(L / 2, Math.min(x1, x2), Math.max(x1, x2));
      const M = P_live * xm * (L - xm) / L;
      const force = M / H;
      return sf * force * 1000 / df * 1e4;
    }
    if (type === 'diagonal') {
      const x = mid[idx];
      const Vmax = P_live * Math.max(x / L, 1 - x / L);
      const frac = side === 'L' ? fracL : fracR;
      const N = frac * Vmax * (Ld / H);
      return sf * N * 1000 / df * 1e4;
    }
    if (type === 'topCross') return 20;
    if (type === 'topLat') {
      const N = 0.2 * P_live;
      return Math.max(sf * N * 1000 / df * 1e4, 9);
    }
    return 5;
  }

  function makeDesign(build, specs, note) {
    return {
      note: note || '',
      nodes: build.nodes,
      members: build.mdefs.map((md, i) => ({
        a: md.a, b: md.b, spec: 'S460 ' + specs[i].id
      }))
    };
  }

  function optimizeCandidate(H, isBox, useTrans) {
    const build = isBox ? buildBox(H, useTrans) : buildCentral(H);
    const mdefs = build.mdefs;

    let specs = mdefs.map(md => {
      const minArea = isBox ? fatigueMinBox(H, md) : fatigueMinCentral(H, md);
      return chooseSection(minArea, minArea);
    });

    let best = null;
    const targetUtil = 0.60;
    const targetFat = 0.80;
    const targetAlpha = 10;
    const targetFreq = 2.50;
    const targetSag = 0.80;
    const targetSway = 0.80;
    const sagLimit = 0.0746;
    const swayLimit = 0.1243;

    for (let iter = 0; iter < 15; iter++) {
      const design = makeDesign(build, specs, 'optimized candidate');
      const res = analyse(design);
      if (!res || res.error) {
        specs = specs.map(s => nextLarger(s));
        continue;
      }

      const mass = res.mass || 1e9;
      const sag = res.sag || 0;
      const sway = res.sway || 0;
      const okAll = res.ok &&
                    res.maxUtil <= targetUtil &&
                    (res.fatigueWorst || 0) <= targetFat &&
                    (res.alphaCr || 0) >= targetAlpha &&
                    (res.frequency || 0) >= targetFreq &&
                    sag <= sagLimit * targetSag &&
                    sway <= swayLimit * targetSway;

      if (okAll) {
        if (!best || mass < best.mass) {
          best = { mass, design, res, targetMet: true };
        }
      }

      let changed = false;
      for (let i = 0; i < mdefs.length; i++) {
        const md = mdefs[i];
        const cur = specs[i];
        const mr = res.members ? res.members[i] : null;
        const util = mr && mr.util ? mr.util : 0;
        const areaMin = isBox ? fatigueMinBox(H, md) : fatigueMinCentral(H, md);
        let reqArea = cur.A;

        if (util > targetUtil) {
          reqArea = cur.A * (util / targetUtil) * 1.05;
        } else if (util < targetUtil * 0.75 && cur.A > areaMin * 1.1) {
          reqArea = Math.max(areaMin, cur.A * 0.95);
        }

        const isChord = md.type === 'topChord' || md.type === 'bottomChord';
        const isBracing = md.type.includes('Lat') || md.type === 'topCross' ||
                          md.type === 'bottomCross' || md.type === 'transBrace';

        if (sag > sagLimit * targetSag && isChord) reqArea = Math.max(reqArea, cur.A * 1.10);
        if ((res.frequency || 0) < targetFreq && isChord) reqArea = Math.max(reqArea, cur.A * 1.05);
        if ((res.alphaCr || 0) < targetAlpha && (isChord || isBracing)) reqArea = Math.max(reqArea, cur.A * 1.10);
        if (sway > swayLimit * targetSway && isBracing) reqArea = Math.max(reqArea, cur.A * 1.10);
        if ((res.fatigueWorst || 0) > targetFat) {
          reqArea = Math.max(reqArea, cur.A * Math.min(2.0, (res.fatigueWorst / targetFat)) * 1.05);
        }

        if (!okAll && util > targetUtil * 0.9) reqArea = Math.max(reqArea, cur.A);

        const newSec = chooseSection(reqArea, areaMin);
        if (newSec.id !== cur.id) {
          specs[i] = newSec;
          changed = true;
        }
      }

      if (!changed) {
        if (!okAll) {
          specs = specs.map(s => nextLarger(s));
          changed = true;
        } else {
          break;
        }
      }
    }

    const finalDesign = makeDesign(build, specs, 'final candidate');
    const finalRes = analyse(finalDesign);

    if (finalRes && !finalRes.error) {
      const sag = finalRes.sag || 0;
      const sway = finalRes.sway || 0;
      const targetOk = finalRes.ok &&
                       finalRes.maxUtil <= targetUtil + 0.05 &&
                       (finalRes.fatigueWorst || 0) <= targetFat + 0.05 &&
                       (finalRes.alphaCr || 0) >= targetAlpha &&
                       (finalRes.frequency || 0) >= targetFreq &&
                       sag <= sagLimit * 0.90 &&
                       sway <= swayLimit * 0.90;

      if (targetOk) {
        if (!best || finalRes.mass < best.mass) {
          best = { mass: finalRes.mass, design: finalDesign, res: finalRes, targetMet: true };
        }
      } else if (!best || !best.targetMet) {
        const safety = (finalRes.maxUtil || 1) + (finalRes.fatigueWorst || 0);
        if (!best || safety < (best.safety || 1e9)) {
          best = { mass: finalRes.mass, design: finalDesign, res: finalRes, targetMet: false, safety };
        }
      }
    }

    if (!best) {
      // very heavy fallback for this candidate
      const heavySpecs = mdefs.map(() => secList[secList.length - 1]);
      const heavyDesign = makeDesign(build, heavySpecs, 'heavy fallback');
      best = { mass: 1e12, design: heavyDesign, res: { ok: false }, targetMet: false };
    }
    return best;
  }

  const candidates = [];
  // Box truss without transverse braces
  for (const H of [5.5, 5.0, 4.5]) {
    candidates.push(optimizeCandidate(H, true, false));
  }
  // Central triangular truss
  for (const H of [5.5, 5.0, 4.5]) {
    candidates.push(optimizeCandidate(H, false, false));
  }

  // If none nominally pass, try box with transverse braces
  const anyFeasible = candidates.some(c => c && c.res && c.res.ok);
  if (!anyFeasible) {
    candidates.push(optimizeCandidate(5.5, true, true));
    candidates.push(optimizeCandidate(5.0, true, true));
  }

  let targetBest = null;
  let okBest = null;
  let anyBest = null;

  for (const c of candidates) {
    if (!c) continue;
    if (c.targetMet) {
      if (!targetBest || c.mass < targetBest.mass) targetBest = c;
    }
    if (c.res && c.res.ok) {
      const safety = (c.res.maxUtil || 0) + (c.res.fatigueWorst || 0);
      if (!okBest || safety < okBest.safety) okBest = { ...c, safety };
    }
    if (!anyBest) anyBest = c;
  }

  const chosen = targetBest || okBest || anyBest;
  if (chosen && chosen.design) return chosen.design;

  // Ultimate fallback: very heavy box with transverse braces
  const build = buildBox(5.5, true);
  const heavySpecs = build.mdefs.map(() => secList[secList.length - 1]);
  return makeDesign(build, heavySpecs, 'ultimate heavy fallback');
}

function design(site, analyse) {
  const xs = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const H = 5.64;
  const mids = [];
  for (let i = 0; i < 9; i++) mids.push((xs[i] + xs[i + 1]) / 2);

  const raw = [
    ['CHS33.7x2.6', 2.54, 3.1],
    ['CHS42.4x3.2', 3.94, 7.6],
    ['CHS48.3x3.2', 4.53, 11.6],
    ['CHS60.3x3.2', 5.74, 23.5],
    ['CHS60.3x4', 7.07, 28.2],
    ['CHS76.1x3.2', 7.33, 48.8],
    ['CHS76.1x4', 9.06, 59.1],
    ['CHS88.9x4', 10.67, 96.3],
    ['CHS88.9x5', 13.18, 116.4],
    ['CHS114.3x4', 13.86, 211.1],
    ['CHS114.3x5', 17.17, 256.9],
    ['CHS139.7x5', 21.16, 480.5],
    ['CHS168.3x5', 25.65, 855.8],
    ['CHS139.7x6.3', 26.4, 588.6],
    ['CHS168.3x6.3', 32.06, 1053.4],
    ['CHS193.7x6.3', 37.09, 1630.0],
    ['CHS193.7x8', 46.67, 2015.5],
    ['CHS219.1x8', 53.06, 2959.6],
    ['CHS244.5x8', 59.44, 4160.4],
    ['CHS273x10', 82.62, 7154.1],
    ['CHS323.9x10', 98.61, 12158.3],
    ['CHS355.6x12.5', 134.74, 19852.2],
    ['CHS406.4x12.5', 154.68, 30030.7],
    ['CHS457x16', 221.67, 53959.4]
  ];
  const sec = raw.map(r => ({ id: r[0], A: r[1], I: r[2] })).sort((a, b) => a.A - b.A);
  const NS = sec.length;

  function specOf(s) { return 'S690 ' + s.id; }
  function idxById(id) {
    for (let i = 0; i < NS; i++) if (sec[i].id === id) return i;
    return 0;
  }

  const baseTop = idxById('CHS168.3x6.3');
  const baseBot = idxById('CHS273x10');
  const baseDiag = idxById('CHS139.7x5');
  const baseCross = idxById('CHS114.3x5');
  const baseLat = idxById('CHS114.3x5');

  function buildWarren() {
    const nodes = [];
    for (let j = 0; j < 9; j++) {
      nodes.push({ id: 'C' + j, x: mids[j], y: -H, z: 0 });
    }

    const members = [];
    const meta = [];

    function add(a, b, type, pos, side) {
      const i = members.length;
      members.push({ a: a, b: b });
      meta.push({ type: type, pos: pos, side: side });
    }

    function addPair(a1, b1, a2, b2, type, pos, key) {
      add(a1, b1, type, pos, 'L');
      add(a2, b2, type, pos, 'R');
    }

    for (let i = 0; i < 9; i++) {
      addPair('L' + i, 'L' + (i + 1), 'R' + i, 'R' + (i + 1), 'top', i);
    }

    for (let j = 0; j < 8; j++) {
      add('C' + j, 'C' + (j + 1), 'bot', j, '');
    }

    for (let j = 0; j < 9; j++) {
      addPair('C' + j, 'L' + j, 'C' + j, 'R' + j, 'diag', j);
      addPair('C' + j, 'L' + (j + 1), 'C' + j, 'R' + (j + 1), 'diag', j);
    }

    for (let i = 0; i < 10; i++) {
      add('L' + i, 'R' + i, 'cross', i, '');
    }

    for (let i = 0; i < 9; i++) {
      if (i % 2 === 0) add('L' + i, 'R' + (i + 1), 'lat', i, '');
      else add('R' + i, 'L' + (i + 1), 'lat', i, '');
    }

    const edgeKey = (a, b) => (a < b ? a + '|' + b : b + '|' + a);
    const byEdge = {};
    for (let i = 0; i < members.length; i++) {
      byEdge[edgeKey(members[i].a, members[i].b)] = i;
    }

    function mirrorNode(name, xm, zm) {
      let pre = name[0];
      let num = parseInt(name.slice(1), 10);
      if (pre === 'C') {
        if (xm) num = 8 - num;
      } else {
        if (xm) num = 9 - num;
        if (zm) pre = (pre === 'L' ? 'R' : 'L');
      }
      return pre + num;
    }

    const symGroups = [];
    const assigned = new Array(members.length).fill(false);

    for (let i = 0; i < members.length; i++) {
      if (assigned[i]) continue;
      const set = {};
      const m = members[i];
      for (let bx = 0; bx < 2; bx++) {
        for (let bz = 0; bz < 2; bz++) {
          const a = mirrorNode(m.a, !!bx, !!bz);
          const b = mirrorNode(m.b, !!bx, !!bz);
          const j = byEdge[edgeKey(a, b)];
          if (j !== undefined) set[j] = true;
        }
      }
      const arr = [];
      for (const k in set) arr.push(parseInt(k, 10));
      for (const j of arr) assigned[j] = true;
      symGroups.push(arr);
    }

    return { nodes: nodes, members: members, meta: meta, symGroups: symGroups };
  }

  function safeAnalyse(d) {
    try {
      const r = analyse(d);
      if (!r) return { error: true };
      return r;
    } catch (e) {
      return { error: true, exception: true };
    }
  }

  function num(v, def) {
    return (typeof v === 'number' && isFinite(v)) ? v : def;
  }

  function isRobust(r) {
    return !!r && !r.error && !!r.ok &&
      num(r.maxUtil, 2) <= 0.66 &&
      num(r.fatigueWorst, 2) <= 0.72 &&
      num(r.alphaCr, 0) >= 11 &&
      num(r.frequency, 0) >= 2.80 &&
      num(r.sag, 1) <= 0.057 &&
      num(r.sway, 1) <= 0.090;
  }

  function isGood(r) {
    return !!r && !r.error && !!r.ok &&
      num(r.maxUtil, 2) <= 0.70 &&
      num(r.fatigueWorst, 2) <= 0.78 &&
      num(r.alphaCr, 0) >= 8.5 &&
      num(r.frequency, 0) >= 2.65 &&
      num(r.sag, 1) <= 0.063 &&
      num(r.sway, 1) <= 0.100;
  }

  function isLoose(r) {
    return !!r && !r.error && !!r.ok &&
      num(r.maxUtil, 2) <= 0.85 &&
      num(r.fatigueWorst, 2) <= 0.90 &&
      num(r.alphaCr, 0) >= 6.0 &&
      num(r.frequency, 0) >= 2.35 &&
      num(r.sag, 1) <= 0.074 &&
      num(r.sway, 1) <= 0.120;
  }

  function makeDesign(build, idxs, note) {
    return {
      note: note || '',
      nodes: build.nodes,
      members: build.members.map((m, i) => ({
        a: m.a,
        b: m.b,
        spec: specOf(sec[idxs[i]])
      }))
    };
  }

  function chooseIdx(reqA, reqI, isComp, currentK) {
    let best = currentK;
    if (isComp && reqI > 0) {
      let cand = -1;
      let candA = 1e99;
      let candI = -1;
      for (let k = 0; k < NS; k++) {
        if (sec[k].I >= reqI && sec[k].A >= reqA * 0.85) {
          if (sec[k].A < candA - 1e-9 ||
              (Math.abs(sec[k].A - candA) < 1e-9 && sec[k].I > candI)) {
            cand = k;
            candA = sec[k].A;
            candI = sec[k].I;
          }
        }
      }
      if (cand < 0) cand = NS - 1;
      best = cand;
    } else {
      let cand = 0;
      while (cand < NS && sec[cand].A < reqA) cand++;
      if (cand >= NS) cand = NS - 1;
      best = cand;
    }
    return best;
  }

  function initialIndex(type, delta) {
    let base;
    if (type === 'top') base = baseTop;
    else if (type === 'bot') base = baseBot;
    else if (type === 'diag') base = baseDiag;
    else if (type === 'cross') base = baseCross;
    else if (type === 'lat') base = baseLat;
    else base = baseDiag;
    return Math.max(0, Math.min(NS - 1, base + delta));
  }

  function optimize(tComp, tTens, maxIter, delta) {
    const build = buildWarren();
    const n = build.members.length;
    let idx = build.members.map((m, i) => initialIndex(build.meta[i].type, delta));

    let bestRobust = null;
    let bestGood = null;
    let bestFallback = null;
    let bestAny = null;

    function applySymmetry() {
      let ch = false;
      for (const g of build.symGroups) {
        let mx = 0;
        for (const j of g) if (idx[j] > mx) mx = idx[j];
        for (const j of g) {
          if (idx[j] !== mx) {
            idx[j] = mx;
            ch = true;
          }
        }
      }
      return ch;
    }

    function bumpTypes(types) {
      let ch = false;
      for (let i = 0; i < n; i++) {
        if (types.indexOf(build.meta[i].type) >= 0) {
          const ni = Math.min(NS - 1, idx[i] + 1);
          if (ni !== idx[i]) {
            idx[i] = ni;
            ch = true;
          }
        }
      }
      return ch;
    }

    for (let iter = 0; iter < maxIter; iter++) {
      const d = makeDesign(build, idx, 'S690 triangular Warren optimization');
      const r = safeAnalyse(d);

      if (!r || r.error) {
        for (let i = 0; i < n; i++) idx[i] = Math.min(NS - 1, idx[i] + 1);
        continue;
      }

      const mass = num(r.mass, 1e12);
      if (!bestAny || mass < bestAny.mass) bestAny = { mass: mass, design: d, res: r };
      if (isRobust(r) && (!bestRobust || mass < bestRobust.mass)) bestRobust = { mass: mass, design: d, res: r };
      if (isGood(r) && (!bestGood || mass < bestGood.mass)) bestGood = { mass: mass, design: d, res: r };
      if (isLoose(r) && (!bestFallback || mass < bestFallback.mass)) bestFallback = { mass: mass, design: d, res: r };

      let changed = false;
      const mres = r.members || [];

      for (let i = 0; i < n; i++) {
        const mr = mres[i];
        if (!mr) continue;

        const util = (mr.util != null && isFinite(mr.util)) ? mr.util : 0;
        const mode = mr.mode ? String(mr.mode) : '';
        const isComp = /comp|buck|euler|column/i.test(mode);
        const isFat = /fatigue/i.test(mode);

        let target = isComp ? tComp : tTens;
        if (isFat) target = tTens;
        if (target <= 0) target = 0.65;

        let factor = util / target;
        if (!isFinite(factor) || factor <= 0) factor = 0.30;
        if (factor < 0.25) factor = 0.25;

        const k = idx[i];
        const cur = sec[k];
        const pA = 1.0;
        const pI = 1.15;

        let reqA = cur.A * Math.pow(factor, 1 / pA);
        let reqI = cur.I * Math.pow(factor, 1 / pI);

        if (factor > 1) {
          reqA *= 1.06;
          reqI *= 1.06;
        } else {
          reqA *= 1.10;
          reqI *= 1.10;
        }

        let nk = chooseIdx(reqA, isComp ? reqI : 0, isComp, k);

        if (util > target * 1.02 && nk <= k) nk = Math.min(NS - 1, k + 1);
        if (util < target * 0.65 && nk >= k && k > 0) nk = k - 1;

        if (nk !== k) {
          idx[i] = nk;
          changed = true;
        }
      }

      if (applySymmetry()) changed = true;

      let bumped = false;
      if (num(r.alphaCr, 0) < 10.2) {
        bumped = bumpTypes(['top', 'bot', 'diag', 'lat', 'cross']) || bumped;
      }
      if (num(r.frequency, 0) < 2.75) {
        bumped = bumpTypes(['top', 'bot', 'diag']) || bumped;
      }
      if (num(r.sag, 1) > 0.058) {
        bumped = bumpTypes(['top', 'bot']) || bumped;
      }
      if (num(r.sway, 1) > 0.095) {
        bumped = bumpTypes(['lat', 'cross', 'diag']) || bumped;
      }
      if (bumped) changed = true;

      if (applySymmetry()) changed = true;

      if (!changed) {
        if (!isGood(r)) {
          for (let i = 0; i < n; i++) idx[i] = Math.min(NS - 1, idx[i] + 1);
        } else {
          break;
        }
      }
    }

    const finalDesign = makeDesign(build, idx, 'S690 triangular Warren final');
    const finalRes = safeAnalyse(finalDesign);

    if (finalRes && !finalRes.error) {
      const mass = num(finalRes.mass, 1e12);
      if (!bestAny || mass < bestAny.mass) bestAny = { mass: mass, design: finalDesign, res: finalRes };
      if (isRobust(finalRes) && (!bestRobust || mass < bestRobust.mass)) bestRobust = { mass: mass, design: finalDesign, res: finalRes };
      if (isGood(finalRes) && (!bestGood || mass < bestGood.mass)) bestGood = { mass: mass, design: finalDesign, res: finalRes };
      if (isLoose(finalRes) && (!bestFallback || mass < bestFallback.mass)) bestFallback = { mass: mass, design: finalDesign, res: finalRes };
    }

    return { bestRobust: bestRobust, bestGood: bestGood, bestFallback: bestFallback, bestAny: bestAny };
  }

  const optA = optimize(0.55, 0.65, 18, 0);
  const optB = optimize(0.60, 0.70, 16, 1);
  const optC = optimize(0.50, 0.60, 18, -1);
  const optD = optimize(0.58, 0.67, 16, -2);

  const opts = [optA, optB, optC, optD];
  let rob = null;
  let good = null;
  let loose = null;
  let any = null;

  for (const o of opts) {
    if (o.bestRobust && (!rob || o.bestRobust.mass < rob.mass)) rob = o.bestRobust;
    if (o.bestGood && (!good || o.bestGood.mass < good.mass)) good = o.bestGood;
    if (o.bestFallback && (!loose || o.bestFallback.mass < loose.mass)) loose = o.bestFallback;
    if (o.bestAny && (!any || o.bestAny.mass < any.mass)) any = o.bestAny;
  }

  function fallbackDesign() {
    const build = buildWarren();
    const idxs = build.members.map((m, i) => {
      const t = build.meta[i].type;
      if (t === 'bot') return idxById('CHS355.6x12.5');
      if (t === 'top') return idxById('CHS244.5x8');
      if (t === 'diag') return idxById('CHS244.5x8');
      if (t === 'cross' || t === 'lat') return idxById('CHS168.3x6.3');
      return idxById('CHS244.5x8');
    });
    return makeDesign(build, idxs, 'conservative S690 fallback');
  }

  const fb = fallbackDesign();
  const fbr = safeAnalyse(fb);

  if (rob) return rob.design;
  if (good) return good.design;
  if (fbr && !fbr.error && fbr.ok) return fb;
  if (loose) return loose.design;
  if (any && any.res && any.res.ok) return any.design;

  const heavyBuild = buildWarren();
  const heavyIdx = heavyBuild.members.map(() => idxById('CHS355.6x12.5'));
  const heavyDesign = makeDesign(heavyBuild, heavyIdx, 'very conservative S690 fallback');
  const heavyRes = safeAnalyse(heavyDesign);
  if (heavyRes && !heavyRes.error && heavyRes.ok) return heavyDesign;

  const ultBuild = buildWarren();
  const ultIdx = ultBuild.members.map(() => idxById('CHS457x16'));
  return makeDesign(ultBuild, ultIdx, 'ultimate S690 fallback');
}

