  const secs = rawSecs.map(r => ({ id: r[0], A: r[1] })).sort((a, b) => a.A - b.A);
  const baseId = 'CHS355.6x12.5';
  let baseIdx = secs.findIndex(s => s.id === baseId);
  if (baseIdx < 0) baseIdx = secs.length - 1;

