  const nGroups = 28;
  const membersMeta = [];
  function addMember(a, b, g) {
    membersMeta.push({ a: a, b: b, g: g });
  }

  function mapTop(i) {
    if (i < 4) return i;
    if (i > 4) return 8 - i;
    return 4;
  }
  function mapBottom(j) {
    return j < 4 ? j : 7 - j;
  }
  function mapDiag(j, e) {
    if (j < 4) return j * 2 + e;
    if (j > 4) return (8 - j) * 2 + (1 - e);
    return 8;
  }
  function mapCross(i) {
    return i < 5 ? i : 9 - i;
  }
  function mapLat(i) {
    if (i < 4) return i;
    if (i > 4) return 8 - i;
    return 4;
  }

  // Top chords L_i-L_{i+1}, R_i-R_{i+1}: groups 0..4
  for (let i = 0; i < 9; i++) {
    const g = mapTop(i);
    addMember('L' + i, 'L' + (i + 1), g);
    addMember('R' + i, 'R' + (i + 1), g);
  }

  // Bottom central chord C_j-C_{j+1}: groups 5..8
  for (let j = 0; j < 8; j++) {
    const g = 5 + mapBottom(j);
    addMember('C' + j, 'C' + (j + 1), g);
  }

  // Diagonals C_j to L/R at x_j and x_{j+1}: groups 9..17
  for (let j = 0; j < 9; j++) {
    for (const side of ['L', 'R']) {
      addMember('C' + j, side + j, 9 + mapDiag(j, 0));
      addMember('C' + j, side + (j + 1), 9 + mapDiag(j, 1));
    }
  }

  // Top transverse members L_i-R_i: groups 18..22
  for (let i = 0; i < 10; i++) {
    addMember('L' + i, 'R' + i, 18 + mapCross(i));
  }

