    return {
      note: 'Symmetric central-spine Warren space truss, S690 CHS, greedily sized for worst-unit robustness',
      nodes: nodes,
      members: mem
    };
  }

  let calls = 0;
  const maxCalls = 255;

  function evalVar(varIdx) {
    if (calls >= maxCalls) return null;
    calls++;
    const d = buildDesign(varIdx);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
