  const lim = {
    maxUtil: 0.55,
    fatigue: 0.60,
    alphaCr: 11.0,
    frequency: 2.65,
    sag: 0.055,
    sway: 0.085
  };

  function passes(r) {
    if (!r || r.error || !r.ok) return false;
    const u = (typeof r.maxUtil === 'number') ? r.maxUtil : 9;
    const f = (typeof r.fatigueWorst === 'number') ? r.fatigueWorst : 9;
    const a = (typeof r.alphaCr === 'number') ? r.alphaCr : 0;
    const fr = (typeof r.frequency === 'number') ? r.frequency : 0;
    const sg = (typeof r.sag === 'number') ? r.sag : 9;
    const sw = (typeof r.sway === 'number') ? r.sway : 9;
    return u <= lim.maxUtil &&
           f <= lim.fatigue &&
           a >= lim.alphaCr &&
           fr >= lim.frequency &&
           sg <= lim.sag &&
           sw <= lim.sway;
  }

  let varIdx = new Array(nGroups).fill(baseIdx);
  let cur = evalVar(varIdx);
  let best = null;

  if (cur && !cur.error && cur.res && passes(cur.res)) {
    best = {
      mass: cur.res.mass,
      varIdx: varIdx.slice(),
      design: cur.design,
      res: cur.res
    };
  } else {
    // Should not normally happen: the all-CHS355.6 baseline is very stiff.
    best = {
      mass: (cur && cur.res && cur.res.mass) ? cur.res.mass : 1e12,
      varIdx: varIdx.slice(),
      design: cur ? cur.design : buildDesign(varIdx),
      res: cur ? cur.res : null
    };
  }

  // Order is deliberate: size main chords first, diagonals next, bracing last.
  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    for (let g = 0; g < nGroups; g++) {
      if (calls >= maxCalls) break;

      let lo = 0;
      let hi = varIdx[g];
      let bestIdx = varIdx[g];
      let bestLocal = null;

      while (lo <= hi) {
        if (calls >= maxCalls) break;
        const mid = Math.floor((lo + hi) / 2);

        let ev;
        if (mid === varIdx[g]) {
          ev = cur;
        } else {
          const trial = varIdx.slice();
          trial[g] = mid;
          ev = evalVar(trial);
        }

        if (ev && !ev.error && ev.res && passes(ev.res)) {
          bestIdx = mid;
          bestLocal = ev;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (bestIdx < varIdx[g] && bestLocal) {
        varIdx[g] = bestIdx;
        cur = bestLocal;
        if (cur.res.mass < best.mass) {
          best = {
            mass: cur.res.mass,
            varIdx: varIdx.slice(),
            design: cur.design,
            res: cur.res
          };
        }
        changed = true;
      }
    }
    if (!changed || calls >= maxCalls) break;
  }

  // Return the lightest design that satisfied all conservative targets.
  if (best && best.design) return best.design;

  // Safety fallback: the original very stiff S690 CHS355.6 section throughout.
  varIdx = new Array(nGroups).fill(baseIdx);
  return buildDesign(varIdx);
}

