    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number') {
      if (r.sag / r.sagLimit > TH.sagRatio) return false;
    }
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number') {
      if (r.sway / r.swayLimit > TH.swayRatio) return false;
    }
    if (r.robustness === false) return false;
    return true;
  }

  function groupLengths(yArr) {
    const topo = buildTopology(yArr);
    const pos = {};
    for (const nd of topo.nodes) pos[nd.id] = nd;
    for (let i = 0; i < 10; i++) {
      pos['L' + i] = { x: xs[i], y: 0, z: -2.65 };
      pos['R' + i] = { x: xs[i], y: 0, z: 2.65 };
    }
    const len = new Array(nGroups).fill(0);
    for (const m of topo.mem) {
      const p = pos[m.a], q = pos[m.b];
      const dx = p.x - q.x, dy = p.y - q.y, dz = p.z - q.z;
      len[m.g] += Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
    return len;
  }

  function optimize(yArr, callLimit) {
    const startCalls = calls;
    const stop = Math.min(MAXCALLS, startCalls + callLimit);

    let idx = new Array(nGroups).fill(baseIdx);
    let cur = evalDesign(yArr, idx);
    if (!cur || !passes(cur.res)) {
      idx = new Array(nGroups).fill(heavyIdx);
      cur = evalDesign(yArr, idx);
      if (!cur || !passes(cur.res)) return null;
    }

    const lens = groupLengths(yArr);
    const order = [];
    for (let g = 0; g < nGroups; g++) {
      if (lens[g] > 0.01) order.push(g);
    }
    order.sort((a, b) => lens[b] - lens[a]);

    for (let pass = 0; pass < 2; pass++) {
      if (calls >= stop) break;
      let changed = false;

      for (let oi = 0; oi < order.length; oi++) {
        if (calls >= stop) break;
        const g = order[oi];
        if (idx[g] <= 0) continue;

        let lo = 0;
        let hi = idx[g];
        let best = idx[g];
        let bestE = null;

        while (lo <= hi && calls < stop) {
          const mid = Math.floor((lo + hi) / 2);
          let ev;
          if (mid === idx[g]) {
            ev = cur;
          } else {
            const trial = idx.slice();
            trial[g] = mid;
            ev = evalDesign(yArr, trial);
          }

          if (ev && !ev.error && passes(ev.res)) {
            best = mid;
            bestE = ev;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (best < idx[g] && bestE && passes(bestE.res)) {
          idx = bestE.idx;
          cur = bestE;
          changed = true;
        }
      }

      if (!changed) break;
    }

    if (cur && passes(cur.res)) {
      return {
