    return buildDesign(yConst, idx);
  }

  results.sort((a, b) => a.mass - b.mass);
  const best = results[0];
  const out = best.design;
  out.note = 'Variable-depth central-spine Warren space truss, parabolic/constant explored; S690 and AL7075 CHS coordinate descent with conservative margins.';
  return out;
}

