    freq: 2.55,
    sag: 0.88,
    sway: 0.88
  };

  function evalDesign(idx, active) {
    const key = idx.join(',') + '|' + active.map(b => b ? 1 : 0).join('');
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;
    calls++;
    const d = buildDesign(idx, active);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      return { error: true, raw: e };
    }
    if (!r || r.error || r.ok === false) {
      const res = { error: true, raw: r };
      cache.set(key, res);
      return res;
    }
    const n = (v, dflt) => (typeof v === 'number' && isFinite(v)) ? v : dflt;
    const pass =
      n(r.maxUtil, 9) <= TH.util &&
      n(r.fatigueWorst, 9) <= TH.fatigue &&
      n(r.alphaCr, 0) >= TH.alpha &&
      n(r.frequency, 0) >= TH.freq &&
      (typeof r.sag === 'number' && typeof r.sagLimit === 'number' ? r.sag / r.sagLimit <= TH.sag : true) &&
      (typeof r.sway === 'number' && typeof r.swayLimit === 'number' ? r.sway / r.swayLimit <= TH.sway : true) &&
      r.robustness !== false;
    const res = {
      design: d,
      res: r,
      idx: idx.slice(),
      active: active.slice(),
      mass: r.mass,
      pass
    };
    cache.set(key, res);
    return res;
  }

  let idx = baseIdx.slice();
  let active = new Array(nGroups).fill(true);
  let cur = evalDesign(idx, active);
  if (!cur || !cur.pass) {
    return buildDesign(baseIdx, active);
  }

  function binaryShrink(g) {
    const current = idx[g];
    if (current <= 0) return false;

    let lo = 0;
    let hi = current - 1;
    let best = current;
    let bestE = null;

    while (lo <= hi && calls < MAX_CALLS) {
      const mid = (lo + hi) >> 1;
      const trial = idx.slice();
      trial[g] = mid;
      const e = evalDesign(trial, active);
      if (e && e.pass) {
        best = mid;
        bestE = e;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    for (let extra = best - 1; extra >= Math.max(0, best - 4); extra--) {
      if (calls >= MAX_CALLS) break;
      const trial = idx.slice();
      trial[g] = extra;
      const e = evalDesign(trial, active);
      if (e && e.pass) {
        best = extra;
        bestE = e;
      }
    }

    if (best < current && bestE) {
      idx = bestE.idx;
      cur = bestE;
      return true;
    }
    return false;
  }

  for (let pass = 0; pass < 2 && calls < MAX_CALLS; pass++) {
    const order = [];
    for (let g = 0; g < nGroups; g++) {
      if (active[g]) order.push(g);
    }
    order.sort((a, b) =>
      (groupLen[b] * all[idx[b]].massPerM) - (groupLen[a] * all[idx[a]].massPerM)
    );
    let changed = false;
    for (let oi = 0; oi < order.length && calls < MAX_CALLS; oi++) {
      const g = order[oi];
      if (idx[g] <= 0) continue;
      if (binaryShrink(g)) changed = true;
    }
    if (!changed) break;
  }

  if (cur && cur.pass) return cur.design;
  return buildDesign(baseIdx, active);
}

