  const LST = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const GROUPS = ['TC', 'BC', 'V', 'D', 'TLc', 'TLd', 'BLc', 'BLd'];

  function build(c) {
    const nodes = [];
    for (let i = 1; i <= 8; i++) {
      nodes.push({ id: 'BL' + i, x: LST[i], y: -DEP, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + i, x: LST[i], y: -DEP, z: ZR, joint: 'pin' });
    }
    const members = [];
    const add = (a, b, spec) => members.push({ a: a, b: b, spec: spec });
    // top chords (deck lines)
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), c.TC);
      add('R' + i, 'R' + (i + 1), c.TC);
    }
    // bottom chords
    for (let i = 1; i < 8; i++) {
      add('BL' + i, 'BL' + (i + 1), c.BC);
      add('BR' + i, 'BR' + (i + 1), c.BC);
    }
    // verticals
    for (let i = 1; i <= 8; i++) {
      add('L' + i, 'BL' + i, c.V);
      add('R' + i, 'BR' + i, c.V);
    }
    // Pratt diagonals: sloping down toward midspan (tension under gravity)
    for (const s of ['L', 'R']) {
      const B = (s === 'L') ? 'BL' : 'BR';
      for (let i = 0; i <= 4; i++) add(s + i, B + (i + 1), c.D);
      for (let i = 4; i <= 8; i++) add(s + (i + 1), B + i, c.D);
    }
    // top wind girder (deck level, y = 0)
    for (let i = 0; i <= 9; i++) add('L' + i, 'R' + i, c.TLc);
    for (let i = 0; i <= 8; i++) add('L' + i, 'R' + (i + 1), c.TLd);
    // bottom wind girder (y = -DEP)
    for (let i = 1; i <= 8; i++) add('BL' + i, 'BR' + i, c.BLc);
    for (let i = 1; i <= 7; i++) add('BL' + i, 'BR' + (i + 1), c.BLd);
