  const CHS = ['88.9x5', '114.3x5', '139.7x5', '168.3x5', '139.7x6.3', '168.3x6.3', '193.7x6.3', '193.7x8', '219.1x8', '244.5x8', '273x10', '323.9x10'];
  const MATS = [
    TIMB.map(t => 'GL28 TIMBER' + t),
    CHS.map(s => 'S355 CHS' + s),
    CHS.map(s => 'S460 CHS' + s)
  ];

  const LIMIT = 370;
  let calls = 0;
  const cache = new Map();

  function ev(c) {
    const key = GROUPS.map(g => c[g]).join('|');
    if (cache.has(key)) return cache.get(key);
    if (calls >= LIMIT) return null;
    calls++;
    let r = null;
    try { r = analyse(build(c)); } catch (e) { r = null; }
    cache.set(key, r);
    return r;
  }

  function ok(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.95) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.95 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.95 * r.swayLimit) return false;
    return true;
  }

  // 1. find a feasible starting point (heavy steel)
  const base = ['S355 CHS273x10', 'S355 CHS323.9x10', 'S355 CHS406.4x12.5', 'S355 CHS457x16'];
  let cur = null, curR = null, lastC = null, lastR = null;
  for (const sp of base) {
    const c = {};
    GROUPS.forEach(g => { c[g] = sp; });
    const r = ev(c);
    lastC = c; lastR = r;
    if (ok(r)) { cur = c; curR = r; break; }
  }
  if (!cur) { cur = lastC; curR = lastR; }

  // 2. coordinate search: per group, bisect each material's size list
  for (let sweep = 0; sweep < 3; sweep++) {
    let improved = false;
    for (const g of GROUPS) {
      let bestC = cur, bestR = curR;
      for (const list of MATS) {
        const withSpec = (k) => { const c = Object.assign({}, cur); c[g] = list[k]; return c; };
        let lo = 0, hi = list.length - 1;
        const rh = ev(withSpec(hi));
        if (!ok(rh)) continue;
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          const rm = ev(withSpec(mid));
          if (ok(rm)) hi = mid; else lo = mid + 1;
        }
        const c = withSpec(lo);
        const r = ev(c);
        if (ok(r) && bestR && (!ok(bestR) || r.mass < bestR.mass)) {
          bestC = c; bestR = r;
        }
      }
      if (bestC !== cur) improved = true;
      cur = bestC; curR = bestR;
    }
    if (!improved || calls >= LIMIT - 40) break;
  }

  const out = build(cur);
  out.note = 'Twin Pratt deck trusses (depth 5.5 m, pin-jointed) with top and bottom wind girders; member groups sized by search against analyse.';
  return out;
}

function design(site, analyse) {
  // Closed box: two Warren deck trusses (depth 5.6 m, pin-jointed), top lateral
  // bracing at deck level (y = 0), bottom lateral bracing at y = -5.6, and end
  // diagonals. Every face is triangulated, so there is no internal mechanism.
  const DEP = 5.6, ZL = -2.65, ZR = 2.65;
  const X = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const XM = [];
  for (let i = 0; i < 9; i++) XM.push(0.5 * (X[i] + X[i + 1]));

  const SECS = ['33.7x2.6', '42.4x3.2', '48.3x3.2', '60.3x3.2', '60.3x4', '76.1x3.2', '76.1x4',
    '88.9x4', '88.9x5', '114.3x4', '114.3x5', '139.7x5', '168.3x5', '139.7x6.3', '168.3x6.3',
    '193.7x6.3', '193.7x8', '219.1x8', '244.5x8', '273x10', '323.9x10', '355.6x12.5',
    '406.4x12.5', '457x16'];
  const MATS = ['S235', 'S355', 'S460'];
  const GROUPS = ['TC', 'BC', 'WB', 'TL', 'BLt', 'END'];

  function build(c) {
    const nodes = [];
    for (let i = 0; i < 9; i++) {
      nodes.push({ id: 'BL' + i, x: XM[i], y: -DEP, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + i, x: XM[i], y: -DEP, z: ZR, joint: 'pin' });
    }
    const m = [];
    const add = (a, b, s) => m.push({ a: a, b: b, spec: s });
    // deck chords
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1), c.TC);
      add('R' + i, 'R' + (i + 1), c.TC);
    }
    // bottom chords
    for (let i = 0; i < 8; i++) {
      add('BL' + i, 'BL' + (i + 1), c.BC);
      add('BR' + i, 'BR' + (i + 1), c.BC);
    }
    // Warren webs
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'BL' + i, c.WB);
      add('BL' + i, 'L' + (i + 1), c.WB);
      add('R' + i, 'BR' + i, c.WB);
      add('BR' + i, 'R' + (i + 1), c.WB);
    }
    // top lateral bracing (deck level)
    for (let i = 0; i <= 9; i++) add('L' + i, 'R' + i, c.TL);
    for (let i = 0; i < 9; i++) add('L' + i, 'R' + (i + 1), c.TL);
    // bottom lateral bracing
    for (let i = 0; i < 9; i++) add('BL' + i, 'BR' + i, c.BLt);
    for (let i = 0; i < 8; i++) add('BL' + i, 'BR' + (i + 1), c.BLt);
    // end diagonals (close the end faces)
    add('L0', 'BR0', c.END);
    add('R0', 'BL0', c.END);
    add('L9', 'BR8', c.END);
    add('R9', 'BL8', c.END);
    return { note: '', nodes: nodes, joints: {}, members: m };
  }

  let calls = 0;
  const cache = new Map();
  function ev(c) {
    const key = GROUPS.map(g => c[g]).join('|');
    if (cache.has(key)) return cache.get(key);
    if (calls >= 385) return null;
    calls++;
    let r = null;
    try { r = analyse(build(c)); } catch (e) { r = null; }
    cache.set(key, r);
    return r;
  }

  // margins for the +-8% strength/thickness spread, imperfection factors and stiffness
  function ok(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.9) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.9) return false;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.05 * r.fMin) return false;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.2 * r.alphaCrMin) return false;
    return true;
  }

  // for one group, find the lightest feasible size per material (bisection on the sorted list)
  function bestFor(g, cur) {
    let best = null, bestR = null;
    for (const mat of MATS) {
      const list = SECS.map(s => mat + ' CHS' + s);
      const withSpec = (k) => { const c = Object.assign({}, cur); c[g] = list[k]; return c; };
      let lo = 0, hi = list.length - 1;
      if (!ok(ev(withSpec(hi)))) continue;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ok(ev(withSpec(mid)))) hi = mid; else lo = mid + 1;
      }
      const c = withSpec(lo);
      const r = ev(c);
      if (ok(r) && (!bestR || r.mass < bestR.mass)) { best = c; bestR = r; }
    }
    return { c: best, r: bestR };
  }

  // 1. feasible start
  let cur = null, curR = null;
  for (const sp of ['S355 CHS273x10', 'S355 CHS457x16']) {
    const c = {};
    GROUPS.forEach(g => { c[g] = sp; });
    const r = ev(c);
    if (ok(r)) { cur = c; curR = r; break; }
  }
  if (!cur) {
    const c = {};
    GROUPS.forEach(g => { c[g] = 'S355 CHS457x16'; });
    const out = build(c);
    out.note = 'Closed Warren box truss, heaviest fallback sizes.';
    return out;
  }

  // 2. coordinate search over groups
  for (let sweep = 0; sweep < 3; sweep++) {
    let improved = false;
    for (const g of GROUPS) {
      const b = bestFor(g, cur);
      if (b.c && b.r && (!curR || b.r.mass < curR.mass - 1e-6)) {
        cur = b.c; curR = b.r; improved = true;
      }
    }
    if (!improved || calls >= 370) break;
  }

  const out = build(cur);
  out.note = 'Closed box of two Warren deck trusses (depth 5.6 m) with top and bottom lateral bracing and end diagonals, all pin-jointed and triangulated; group sizes searched with margins.';
  return out;
}

function design(site, analyse) {
  const T0 = Date.now();
  const LIMIT_MS = 72000;
  const H = 5.62, ZL = -2.65, ZR = 2.65;
  const X = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];

  // S355 CHS/SHS candidates (area cm2, strong-axis I cm4), sorted by area
  const RAW = [
    ['CHS', '33.7x2.6', 2.54, 3.1], ['CHS', '42.4x3.2', 3.94, 7.6], ['CHS', '48.3x3.2', 4.53, 11.6],
    ['CHS', '60.3x3.2', 5.74, 23.5], ['CHS', '60.3x4', 7.07, 28.2], ['CHS', '76.1x3.2', 7.33, 48.8],
    ['CHS', '76.1x4', 9.06, 59.1], ['CHS', '88.9x4', 10.67, 96.3], ['CHS', '88.9x5', 13.18, 116.4],
    ['CHS', '114.3x4', 13.86, 211.1], ['CHS', '114.3x5', 17.17, 256.9], ['CHS', '139.7x5', 21.16, 480.5],
    ['CHS', '139.7x6.3', 26.4, 588.6], ['CHS', '168.3x5', 25.65, 855.8], ['CHS', '168.3x6.3', 32.06, 1053.4],
    ['CHS', '193.7x6.3', 37.09, 1630], ['CHS', '193.7x8', 46.67, 2015.5], ['CHS', '219.1x8', 53.06, 2959.6],
    ['CHS', '244.5x8', 59.44, 4160.4], ['CHS', '273x10', 82.62, 7154.1], ['CHS', '323.9x10', 98.61, 12158.3],
    ['CHS', '355.6x12.5', 134.74, 19852.2], ['CHS', '406.4x12.5', 154.68, 30030.7], ['CHS', '457x16', 221.67, 53959.4],
    ['SHS', '40x3', 4.44, 10.2], ['SHS', '50x3', 5.64, 20.8], ['SHS', '60x4', 8.96, 47.1],
    ['SHS', '70x4', 10.56, 76.9], ['SHS', '80x5', 15, 141.3], ['SHS', '90x5', 17, 205.4],
    ['SHS', '100x5', 19, 286.6], ['SHS', '100x8', 29.44, 418.4], ['SHS', '120x6', 27.36, 594.3],
    ['SHS', '140x6', 32.16, 964.4], ['SHS', '150x8', 45.44, 1531.9], ['SHS', '180x8', 55.04, 2719.7],
    ['SHS', '200x10', 76, 4585.3], ['SHS', '250x10', 96, 9232], ['SHS', '300x12.5', 143.75, 19840.5],
    ['SHS', '350x16', 213.76, 39834.9]
  ];
  const CAND = RAW.map(r => ({ spec: 'S355 ' + r[0] + r[1], A: r[2], I: r[3] }))
    .sort((p, q) => p.A - q.A);
  const START = CAND.findIndex(c => c.spec === 'S355 CHS219.1x8');
  const HEAVY = CAND.findIndex(c => c.spec === 'S355 CHS323.9x10');
  const MINI = CAND.findIndex(c => c.A >= 5.7);

  // Topology: two pin-jointed trusses at z = +-2.65 with top and bottom X-bracing.
  // kind 'zig': bottom nodes at odd deck positions, zigzag webs (4.144 m projection), verticals at odd nodes.
  // kind 'mid': classic Warren with bottom nodes at panel midpoints.
  function topo(kind) {
    const nodes = [], members = [];
    const bl = [];
    if (kind === 'zig') { for (const k of [1, 3, 5, 7, 9]) bl.push({ k: k, x: X[k] }); }
    else { for (let k = 0; k <= 8; k++) bl.push({ k: k, x: 0.5 * (X[k] + X[k + 1]) }); }
    const bn = (s, k) => 'B' + s + k;
    for (const b of bl) {
      nodes.push({ id: bn('L', b.k), x: b.x, y: -H, z: ZL, joint: 'pin' });
      nodes.push({ id: bn('R', b.k), x: b.x, y: -H, z: ZR, joint: 'pin' });
    }
    const add = (a, b, role, xm) => members.push({ a: a, b: b, role: role, xm: xm, end: (xm < 5 || xm > 32.3) });
    for (const s of ['L', 'R']) {
      for (let i = 0; i <= 8; i++) add(s + i, s + (i + 1), 'TC', 0.5 * (X[i] + X[i + 1]));
      for (let p = 0; p + 1 < bl.length; p++)
        add(bn(s, bl[p].k), bn(s, bl[p + 1].k), 'BC', 0.5 * (bl[p].x + bl[p + 1].x));
      if (kind === 'zig') {
        for (let i = 0; i <= 8; i++) {
          const xm = 0.5 * (X[i] + X[i + 1]);
          if (i % 2 === 0) add(s + i, bn(s, i + 1), 'WB', xm);
          else add(bn(s, i), s + (i + 1), 'WB', xm);
        }
        for (const k of [1, 3, 5, 7, 9]) add(s + k, bn(s, k), 'VT', X[k]);
      } else {
        for (let k = 0; k <= 8; k++) {
          const xm = 0.5 * (X[k] + X[k + 1]);
          add(s + k, bn(s, k), 'WB', 0.5 * (X[k] + xm));
          add(bn(s, k), s + (k + 1), 'WB', 0.5 * (X[k + 1] + xm));
        }
      }
    }
    for (let i = 0; i <= 9; i++) add('L' + i, 'R' + i, 'TLS', X[i]);
    for (let i = 0; i <= 8; i++) {
      const xm = 0.5 * (X[i] + X[i + 1]);
      add('L' + i, 'R' + (i + 1), 'TLD', xm);
      add('R' + i, 'L' + (i + 1), 'TLD', xm);
    }
    for (const b of bl) add(bn('L', b.k), bn('R', b.k), 'BLS', b.x);
    for (let p = 0; p + 1 < bl.length; p++) {
      const xm = 0.5 * (bl[p].x + bl[p + 1].x);
      add(bn('L', bl[p].k), bn('R', bl[p + 1].k), 'BLD', xm);
      add(bn('R', bl[p].k), bn('L', bl[p + 1].k), 'BLD', xm);
    }
    return { nodes: nodes, members: members };
  }

  function mapMembers(r, mem) {
    if (!r.members || !r.members.length) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    return mem.map((m, j) => {
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e || typeof e.util !== 'number') return null;
      return { util: e.util, mode: String(e.mode || '') };
    });
  }

  // fully-stressed resizing: pick the lightest candidate that brings utilisation to target
  function pick(m, util, mode, gm, v) {
    const md = String(mode || '');
    const fat = /fatig/i.test(md);
    const tens = /tension/i.test(md);
    const T = fat ? 0.85 : (m.end ? 0.60 : 0.70) * gm;
    const u = Math.max(util, 0.03);
    const ratio = u / T;
    const cur = CAND[v];
    const Areq = cur.A * ratio;
    const Ireq = cur.I * ratio;
    const useI = !(fat || tens);
    let k = MINI;
    while (k < CAND.length - 1 && !(CAND[k].A >= Areq && (!useI || CAND[k].I >= Ireq))) k++;
    return k;
  }

  function search(kind, maxIt) {
    const tp = topo(kind);
    const mem = tp.members;
    let st = new Array(mem.length).fill(START);
    let gm = 1.0;
    let best = null;
    const seen = new Set();
    for (let it = 0; it < maxIt; it++) {
      if (Date.now() - T0 > LIMIT_MS) break;
      const key = st.join(',') + '|' + gm.toFixed(3);
      if (seen.has(key)) break;
      seen.add(key);
      const d = {
        note: '', nodes: tp.nodes, joints: {},
        members: mem.map((m, j) => ({ a: m.a, b: m.b, spec: CAND[st[j]].spec }))
      };
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      const mm = mapMembers(r, mem);
      if (!mm) { st = st.map(v => Math.min(CAND.length - 1, v + 3)); continue; }
      const glob = (r.sag > 0.92 * r.sagLimit) || (r.sway > 0.92 * r.swayLimit) ||
        (r.frequency < 1.05 * r.fMin) || (r.alphaCr < 1.2 * r.alphaCrMin);
      const feas = !!r.ok && !glob && !(r.maxUtil > 0.9) && !(r.fatigueWorst > 0.92);
      if (feas && (!best || r.mass < best.mass)) best = { mass: r.mass, d: d };
      if (glob) gm *= 0.93;
      let changed = false;
      const nst = st.map((v, j) => {
        const e = mm[j];
        if (!e) return v;
        const k = pick(mem[j], e.util, e.mode, gm, v);
        if (k !== v) changed = true;
        return k;
      });
      st = nst;
      if (!changed && !glob) break;
    }
    return best;
  }

  let best = search('zig', 60);
  if (Date.now() - T0 < 30000) {
    const b2 = search('mid', 60);
    if (b2 && (!best || b2.mass < best.mass)) best = b2;
  }
  if (best) {
    const out = best.d;
    out.note = 'Two pin-jointed zigzag-web deck trusses (depth 5.62 m, bottom nodes at alternate deck panels with verticals) with top and bottom X-bracing; every member sized individually by fully-stressed iteration on analyse feedback, S355 CHS/SHS only, targets 0.70 static / 0.85 fatigue, 0.60 in end panels.';
    return out;
  }
  const tp = topo('zig');
  return {
    note: 'Fallback: heavy uniform zigzag truss, S355 CHS323.9x10 everywhere.',
    nodes: tp.nodes, joints: {},
    members: tp.members.map(m => ({ a: m.a, b: m.b, spec: 'S355 CHS323.9x10' }))
  };
}

