    if (!r) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return true;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return true;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.05 * r.fMin) return true;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.2 * r.alphaCrMin) return true;
    return false;
  }

  function mapMembers(r) {
    if (!r || !Array.isArray(r.members) || !r.members.length) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    return mem.map((m, j) => {
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a] || byId[m.a + '_' + m.b] || byId[m.b + '_' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e || typeof e.util !== 'number') return null;
      return { util: e.util, mode: String(e.mode || '') };
    });
  }

  // Fully-stressed choice: smallest candidate meeting the target utilisation.
  // Fatigue scales with area only; static strength with A*fy; buckling also with I.
  function pick(k, util, mode, gm) {
    const cur = CAND[k];
    const md = String(mode || '');
    const fat = /fatig/i.test(md);
    const T = (fat ? 0.80 : 0.75) * gm;
    const ratio = Math.max(util, 0.02) / T;
    for (let n = FLOOR; n < CAND.length; n++) {
      const c = CAND[n];
      if (fat) {
        if (c.A < cur.A * ratio) continue;
      } else {
        if (c.A * c.fy < cur.A * cur.fy * ratio) continue;
        if (c.I < cur.I * ratio) continue;
      }
      return n;
    }
    return CAND.length - 1;
  }

  // Fully-stressed iteration on analyse feedback, with a global stiffness guard.
  let sz = mem.map(() => START);
  let gm = 1.0;
  let best = null;
  for (let it = 0; it < 40; it++) {
    if (Date.now() - T0 > 70000) break;
    const d = build(sz);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) break;
    const feas = okR(r);
    if (feas && (!best || r.mass < best.mass)) best = { mass: r.mass, sz: sz.slice() };
    if (globBad(r)) gm *= 0.93;
    const mm = mapMembers(r);
    if (!mm) break;
    let changed = false;
    const nsz = sz.map((k, j) => {
      const e = mm[j];
      if (!e) return k;
      const n = pick(k, e.util, e.mode, gm);
      if (n !== k) changed = true;
      return n;
    });
    if (!changed && feas) break;
    sz = nsz;
  }

  if (best) {
    const d = build(best.sz);
    d.note = 'Attempt-2 closed Warren box, every member sized individually by fully-stressed iteration on analyse feedback (S690/S460/S355/S235 CHS/SHS), fatigue-governed areas, with a global stiffness guard.';
    return d;
  }

  // Fallback: the attempt-2 design, known to pass.
  const FB = { TC: 'S355 CHS244.5x8', BC: 'S355 CHS219.1x8', WB: 'S355 CHS273x10',
                TL: 'S235 CHS244.5x8', BLt: 'S355 CHS273x10', END: 'S235 CHS219.1x8' };
  return {
    note: 'Fallback: closed Warren box of attempt 2.',
    nodes: nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: mem.map(e => ({ a: e.a, b: e.b, spec: FB[e.g] }))
  };
}

function design(site, analyse) {
