  const X = [0, 4.144, 8.289, 12.433, 16.578, 20.722, 24.867, 29.011, 33.156, 37.3];
  const XM = [];
  for (let i = 0; i < 9; i++) XM.push(0.5 * (X[i] + X[i + 1]));

  // [name, A cm2, I cm4, wall mm]
  const CHS = [
    ['33.7x2.6', 2.54, 3.1, 2.6], ['42.4x3.2', 3.94, 7.6, 3.2], ['48.3x3.2', 4.53, 11.6, 3.2],
    ['60.3x3.2', 5.74, 23.5, 3.2], ['60.3x4', 7.07, 28.2, 4], ['76.1x3.2', 7.33, 48.8, 3.2],
    ['76.1x4', 9.06, 59.1, 4], ['88.9x4', 10.67, 96.3, 4], ['88.9x5', 13.18, 116.4, 5],
    ['114.3x4', 13.86, 211.1, 4], ['114.3x5', 17.17, 256.9, 5], ['139.7x5', 21.16, 480.5, 5],
    ['139.7x6.3', 26.4, 588.6, 6.3], ['168.3x5', 25.65, 855.8, 5], ['168.3x6.3', 32.06, 1053.4, 6.3],
    ['193.7x6.3', 37.09, 1630, 6.3], ['193.7x8', 46.67, 2015.5, 8], ['219.1x8', 53.06, 2959.6, 8],
    ['244.5x8', 59.44, 4160.4, 8], ['273x10', 82.62, 7154.1, 10], ['323.9x10', 98.61, 12158.3, 10],
    ['355.6x12.5', 134.74, 19852.2, 12.5], ['406.4x12.5', 154.68, 30030.7, 12.5], ['457x16', 221.67, 53959.4, 16]
  ];
  const SHS = [
    ['40x3', 4.44, 10.2, 3], ['50x3', 5.64, 20.8, 3], ['60x4', 8.96, 47.1, 4], ['70x4', 10.56, 76.9, 4],
    ['80x5', 15, 141.3, 5], ['90x5', 17, 205.4, 5], ['100x5', 19, 286.6, 5], ['100x8', 29.44, 418.4, 8],
    ['120x6', 27.36, 594.3, 6], ['140x6', 32.16, 964.4, 6], ['150x8', 45.44, 1531.9, 8],
    ['180x8', 55.04, 2719.7, 8], ['200x10', 76, 4585.3, 10], ['250x10', 96, 9232, 10],
    ['300x12.5', 143.75, 19840.5, 12.5], ['350x16', 213.76, 39834.9, 16]
  ];
  // [name, A cm2, Iy cm4 (strong), Iz cm4 (weak)]
  const TIM = [
    ['90x180', 162, 4374, 1093.5], ['115x225', 258.75, 10916, 2851.6], ['140x270', 378, 22963.5, 6174],
    ['160x315', 504, 41674.5, 10752], ['190x360', 684, 73872, 20577], ['190x450', 855, 144281.3, 25721.3],
    ['215x540', 1161, 282123, 44722.7], ['240x630', 1512, 500094, 72576],
    ['280x720', 2016, 870912, 131712], ['320x900', 2880, 1944000, 245760]
  ];

  function mkSteel(mat, fy, sf, fam, s) {
    const t = s[3];
    const f = Math.max(0.3, (t - 0.6) / t); // 0.6 mm corrosion loss for capacity
    return {
      spec: mat + ' ' + fam + s[0], A: s[1], Ae: s[1] * f, I: s[2] * f, fy: fy, sf: sf, tf: 0.92,
      E: 210000, dsig: 90, alpha: 0.21, mass: s[1] * 7850e-4
    };
  }
  function mkTim(s) {
    return {
      spec: 'GL28 TIMBER' + s[0], A: s[1], Ae: s[1], I: Math.min(s[2], s[3]), fy: 22, sf: 0.85, tf: 0.98,
      E: 12600, dsig: 8, alpha: 0.49, mass: s[1] * 420e-4
    };
  }

  const CAND = [];
  const STEEL = [['S235', 235, 0.95], ['S355', 355, 0.94], ['S460', 460, 0.93], ['S690', 690, 0.92]];
  for (const g of STEEL) {
    for (const s of CHS) CAND.push(mkSteel(g[0], g[1], g[2], 'CHS', s));
    for (const s of SHS) CAND.push(mkSteel(g[0], g[1], g[2], 'SHS', s));
  }
  for (const s of TIM) CAND.push(mkTim(s));
  CAND.sort((p, q) => (p.mass - q.mass) || (q.fy - p.fy));
  const START = Math.max(0, CAND.findIndex(c => c.spec === 'S355 CHS273x10'));

  // Utilisation of candidate c for member of length L (m) with tension Nt, compression Nc (kN),
  // fatigue stress range carried by force Fr (kN). Worst-case strength / thickness factors applied.
  function utilOf(c, L, Nt, Nc, Fr) {
    const Am = c.Ae * 100 * c.tf;                    // mm2
    const Tcap = Am * c.fy * c.sf / 1.17 / 1000;     // kN
    const Lmm = L * 1000;
    const Ncr = Math.PI * Math.PI * c.E * (c.I * 1e4) / (Lmm * Lmm) / 1000; // kN
    const lam = Math.sqrt(Am * c.fy / 1000 / Math.max(Ncr, 1e-6));
    const a = c.alpha * 1.2;
    let chi = 1;
    if (lam > 0.2) {
      const phi = 0.5 * (1 + a * (lam - 0.2) + lam * lam);
      chi = 1 / (phi + Math.sqrt(Math.max(0, phi * phi - lam * lam)));
      if (chi > 1) chi = 1;
    }
    const Ccap = chi * Tcap;
    const us = Math.max(Nt / Tcap, Nc / Ccap);
    const uf = (Fr * 1000 / Am) / c.dsig;
    return { us: us, uf: uf };
  }

  function pick(c0, L, Nt, Nc, Fr, Ts, Tf) {
    let bi = 0, bs = Infinity;
    for (let k = 0; k < CAND.length; k++) {
      const u = utilOf(CAND[k], L, Nt, Nc, Fr);
      const sc = Math.max(u.us / Ts, u.uf / Tf);
      if (sc <= 1) return k;          // list sorted by mass: first pass is lightest
      if (sc < bs) { bs = sc; bi = k; }
    }
    return bi;
  }

  function feasible(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.8) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.85) return false;
    if (typeof r.sag === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.frequency === 'number' && r.frequency < 1.1 * r.fMin) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < 1.25 * r.alphaCrMin) return false;
    return true;
  }

  function globBad(r) {
    return (r.sag > 0.8 * r.sagLimit) || (r.sway > 0.8 * r.swayLimit) ||
      (r.frequency < 1.2 * r.fMin) || (r.alphaCr < 1.5 * r.alphaCrMin);
  }

  function mapMembers(r, mem) {
    if (!r || !Array.isArray(r.members) || r.members.length === 0) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    const out = [];
    for (let j = 0; j < mem.length; j++) {
      const m = mem[j];
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a] || byId[m.a + '_' + m.b] || byId[m.b + '_' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e || typeof e.util !== 'number') return null;
      out.push({
        util: e.util,
        mode: String(e.mode || ''),
        t: typeof e.tension === 'number' ? Math.abs(e.tension) : null,
        c: typeof e.compression === 'number' ? Math.abs(e.compression) : null
      });
    }
    return out;
  }

  function topo(kind, xTop, xBot, endD) {
    const nlat = kind === 'nlat';
    const bx = nlat ? X : XM;
    const nb = bx.length;
    const nodes = [];
    for (let i = 0; i < nb; i++) {
      nodes.push({ id: 'BL' + i, x: bx[i], y: -H, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + i, x: bx[i], y: -H, z: ZR, joint: 'pin' });
    }
    const mem = [];
    const add = (a, b) => mem.push({ a: a, b: b });
    for (const s of ['L', 'R']) {
      const B = i => 'B' + s + i;
      for (let i = 0; i < 9; i++) add(s + i, s + (i + 1));          // top chord
      for (let i = 0; i < nb - 1; i++) add(B(i), B(i + 1));         // bottom chord
      if (nlat) {
        for (let k = 0; k < 10; k++) add(s + k, B(k));              // verticals
        for (let k = 0; k < 9; k++) {                               // one diagonal per panel
          if (k % 2 === 0) add(s + k, B(k + 1)); else add(B(k), s + (k + 1));
        }
      } else {
        for (let i = 0; i < 9; i++) { add(s + i, B(i)); add(B(i), s + (i + 1)); }   // Warren
      }
    }
    // top lateral (deck level)
    for (let k = 0; k < 10; k++) add('L' + k, 'R' + k);
    for (let k = 0; k < 9; k++) {
      if (xTop) { add('L' + k, 'R' + (k + 1)); add('R' + k, 'L' + (k + 1)); }
      else if (k % 2 === 0) add('L' + k, 'R' + (k + 1));
      else add('R' + k, 'L' + (k + 1));
    }
    // bottom lateral
    for (let i = 0; i < nb; i++) add('BL' + i, 'BR' + i);
    for (let i = 0; i < nb - 1; i++) {
      if (xBot) { add('BL' + i, 'BR' + (i + 1)); add('BR' + i, 'BL' + (i + 1)); }
      else if (i % 2 === 0) add('BL' + i, 'BR' + (i + 1));
      else add('BR' + i, 'BL' + (i + 1));
    }
    if (endD && !nlat) { add('L0', 'BR0'); add('R0', 'BL0'); add('L9', 'BR8'); add('R9', 'BL8'); }

    const P = {};
    for (let i = 0; i < 10; i++) { P['L' + i] = [X[i], 0, ZL]; P['R' + i] = [X[i], 0, ZR]; }
    for (const n of nodes) P[n.id] = [n.x, n.y, n.z];
    const len = mem.map(m => {
      const p = P[m.a], q = P[m.b];
      return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
    });
    return { kind: kind, nodes: nodes, mem: mem, len: len };
  }

  function buildDesign(T, sz) {
    return {
      note: '',
      nodes: T.nodes.map(n => Object.assign({}, n)),
      joints: {},
      members: T.mem.map((m, j) => ({ a: m.a, b: m.b, spec: CAND[sz[j]].spec }))
    };
  }

  function run(T) {
    const nm = T.mem.length;
    let sz = new Array(nm).fill(START);
    const Fr = new Array(nm).fill(null);   // upper bound on traffic stress-range force (kN)
    let g = 1.0, gf = 1.0;
    let best = null;
    const seen = new Set();
    for (let it = 0; it < 40; it++) {
      if (Date.now() - T0 > LIMIT) break;
      const key = sz.join(',') + '|' + g.toFixed(3) + '|' + gf.toFixed(3);
      if (seen.has(key)) break;
      seen.add(key);
      const d = buildDesign(T, sz);
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      const ok = feasible(r);
      if (ok && (!best || r.mass < best.mass)) best = { mass: r.mass, d: d };
      if (globBad(r)) g *= 1.12;
      if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.82) gf *= 1.08;
      const mm = mapMembers(r, T.mem);
      if (!mm) break;
      for (let j = 0; j < nm; j++) {
        const e = mm[j], c = CAND[sz[j]];
        if (e.t === null && e.c === null) {
          const cap = c.Ae * 100 * c.tf * c.fy * c.sf / 1.17 / 1000;
          e.t = 0.5 * e.util * cap; e.c = 0.5 * e.util * cap;
        } else {
          if (e.t === null) e.t = 0;
          if (e.c === null) e.c = 0;
        }
        // fatigue util <= max util, so this is a valid upper bound on the traffic stress range force
        const bound = e.util * c.dsig * c.Ae * 100 * c.tf / 1000;
        if (Fr[j] === null || bound < Fr[j]) Fr[j] = bound;
      }
      const Ts = 0.72 / g, Tf = 0.78 / gf;
      let changed = false;
      const nsz = new Array(nm);
      for (let j = 0; j < nm; j++) {
        const e = mm[j];
        const k = pick(sz[j], T.len[j], e.t, e.c, Fr[j], Ts, Tf);
        nsz[j] = k;
        if (k !== sz[j]) changed = true;
      }
      if (!changed) break;
      sz = nsz;
    }
    return best;
  }

  const runs = [
    topo('warren', true, false, true),
    topo('nlat', false, false, false),
    topo('warren', false, false, true)
  ];
  let best = null;
  for (const T of runs) {
    if (Date.now() - T0 > LIMIT) break;
    const b = run(T);
    if (b && (!best || b.mass < best.mass)) best = b;
  }
  if (best) {
    best.d.note = 'Warren/N-truss box with per-member fully-stressed sizing over steel CHS/SHS and glulam, timber chosen where traffic fatigue governs (Delta-sigma 8 vs 90 MPa), pinned joints, stiffness guard.';
    return best.d;
  }
  const T = runs[0];
  return {
    note: 'Fallback: Warren box, uniform S355 CHS273x10.',
    nodes: T.nodes.map(n => Object.assign({}, n)),
    joints: {},
    members: T.mem.map(m => ({ a: m.a, b: m.b, spec: 'S355 CHS273x10' }))
  };
}

