    const Af = c.Ae * 0.1 * c.fy;                       // kN
    const Ie = c.I * 1e-8;                              // m4
    const Ncr = Math.PI * Math.PI * c.E * 1000 * Ie / (L * L);
    const lam = Math.sqrt(Af / Math.max(Ncr, 1e-9));
    let chi = 1;
    if (lam > 0.2) {
      const phi = 0.5 * (1 + c.al * (lam - 0.2) + lam * lam);
      chi = 1 / (phi + Math.sqrt(Math.max(0, phi * phi - lam * lam)));
      if (chi > 1) chi = 1;
    }
    return { T: Af / 1.17, C: chi * Af / 1.17 };
  }

  // ---------- topologies ----------
  function finish(nodes, mem) {
    const P = {};
    for (let i = 0; i < 10; i++) { P['L' + i] = [X[i], 0, ZL]; P['R' + i] = [X[i], 0, ZR]; }
    for (const n of nodes) P[n.id] = [n.x, n.y, n.z];
    const len = mem.map(m => {
      const p = P[m.a], q = P[m.b];
      return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
    });
    return { nodes: nodes, mem: mem, len: len };
  }

  // N-truss: verticals at every deck node, alternating diagonals, one zigzag lateral diagonal per bay
  function topoN() {
    const nodes = [], mem = [];
    const add = (a, b) => mem.push({ a: a, b: b });
    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'BL' + i, x: X[i], y: -H, z: ZL });
      nodes.push({ id: 'BR' + i, x: X[i], y: -H, z: ZR });
    }
    for (const s of ['L', 'R']) {
      const B = 'B' + s;
      for (let i = 0; i < 9; i++) { add(s + i, s + (i + 1)); add(B + i, B + (i + 1)); }
      for (let i = 0; i < 10; i++) add(s + i, B + i);
      for (let i = 0; i < 9; i++) {
        if (i % 2 === 0) add(s + i, B + (i + 1)); else add(B + i, s + (i + 1));
      }
    }
    for (let i = 0; i < 10; i++) { add('L' + i, 'R' + i); add('BL' + i, 'BR' + i); }
    for (let k = 0; k < 9; k++) {
      if (k % 2 === 0) { add('L' + k, 'R' + (k + 1)); add('BL' + k, 'BR' + (k + 1)); }
      else { add('R' + k, 'L' + (k + 1)); add('BR' + k, 'BL' + (k + 1)); }
    }
    return finish(nodes, mem);
  }

  // Warren box (attempt-5 topology family)
  function topoW(xTop, endD) {
    const nodes = [], mem = [];
    const add = (a, b) => mem.push({ a: a, b: b });
    for (let i = 0; i < 9; i++) {
      nodes.push({ id: 'BL' + i, x: XM[i], y: -H, z: ZL });
      nodes.push({ id: 'BR' + i, x: XM[i], y: -H, z: ZR });
    }
    for (const s of ['L', 'R']) {
      const B = 'B' + s;
      for (let i = 0; i < 9; i++) add(s + i, s + (i + 1));
      for (let i = 0; i < 8; i++) add(B + i, B + (i + 1));
      for (let i = 0; i < 9; i++) { add(s + i, B + i); add(B + i, s + (i + 1)); }
    }
    for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);
    for (let k = 0; k < 9; k++) {
      if (xTop) { add('L' + k, 'R' + (k + 1)); add('R' + k, 'L' + (k + 1)); }
      else if (k % 2 === 0) add('L' + k, 'R' + (k + 1));
      else add('R' + k, 'L' + (k + 1));
    }
    for (let i = 0; i < 9; i++) add('BL' + i, 'BR' + i);
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) add('BL' + i, 'BR' + (i + 1)); else add('BR' + i, 'BL' + (i + 1));
    }
    if (endD) { add('L0', 'BR0'); add('R0', 'BL0'); add('L9', 'BR8'); add('R9', 'BL8'); }
    return finish(nodes, mem);
  }

  function build(Tp, sz) {
    return {
      note: '',
      nodes: Tp.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: 'pin' })),
      joints: {},
      members: Tp.mem.map((m, j) => ({ a: m.a, b: m.b, spec: CAND[sz[j]].spec }))
    };
  }

  function mapMembers(r, mem) {
    if (!r || !Array.isArray(r.members) || r.members.length === 0) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    const out = [];
    for (let j = 0; j < mem.length; j++) {
      const m = mem[j];
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a] || byId[m.a + '_' + m.b] || byId[m.b + '_' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e) { out.push(null); continue; }
      out.push({
        util: typeof e.util === 'number' ? e.util : 0,
        t: typeof e.tension === 'number' ? Math.abs(e.tension) : 0,
        c: typeof e.compression === 'number' ? Math.abs(e.compression) : 0
      });
    }
    return out;
  }

  function strictOk(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.85) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.85) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.85 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.85 * r.swayLimit) return false;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.1 * r.fMin) return false;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.2 * r.alphaCrMin) return false;
    return true;
  }

  function globBad(r) {
    if (!r) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.8 * r.sagLimit) return true;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.8 * r.swayLimit) return true;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.2 * r.fMin) return true;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.5 * r.alphaCrMin) return true;
    return false;
  }

  // Lightest candidate whose predicted utilisation meets tgt.
  // Static: from reported tension/compression envelopes with our own capacity formulas.
  // Fatigue/any mode: reported util scaled by (stress-range capacity ratio), a conservative bound.
  function choose(cur, L, util, T, C, tgt) {
    const cc = CAND[cur];
    const fat = Math.max(0, util) * cc.ds * cc.Ae;   // ~ traffic stress-range force bound (kN*MPa*cm2 units)
    let pick = -1, pu = Infinity;
    for (let n = 0; n < CAND.length; n++) {
      const c = CAND[n];
      const k = caps(c, L);
      let u = fat / (c.ds * c.Ae);
      if (T > 0) u = Math.max(u, T / k.T);
      if (C > 0) u = Math.max(u, C / k.C);
      if (u <= tgt) return n;
      if (u < pu) { pu = u; pick = n; }
    }
    return pick < 0 ? cur : pick;
  }

  function fsd(Tp, tgt0) {
    const nm = Tp.mem.length;
    let sz = new Array(nm).fill(START);
    let g = 1.0;
    let best = null;
    const seen = {};
    for (let it = 0; it < 26; it++) {
      if (Date.now() - T0 > LIMIT) break;
      const key = sz.join(',') + '|' + g.toFixed(3);
      if (seen[key]) break;
      seen[key] = 1;
      const d = build(Tp, sz);
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      const ok = strictOk(r);
      if (ok && (!best || r.mass < best.mass)) best = { mass: r.mass, d: d };
      if (globBad(r)) g = Math.max(0.5, g * 0.9);
      const mm = mapMembers(r, Tp.mem);
      if (!mm) break;
      const tgt = tgt0 * g;
      let changed = false;
      const nsz = sz.map((k, j) => {
        const e = mm[j];
        if (!e) return k;
        const n = choose(k, Tp.len[j], e.util, e.t, e.c, tgt);
        if (n !== k) changed = true;
        return n;
      });
      if (!changed) {
        if (ok) break;
        g = Math.max(0.5, g * 0.92);
      }
      sz = nsz;
    }
    return best;
  }

  const TN = topoN();
  const TW = topoW(true, true);
  let best = null;
  for (const Tp of [TN, TW]) {
    if (Date.now() - T0 > LIMIT) break;
    const b = fsd(Tp, 0.75);
    if (b && (!best || b.mass < best.mass)) best = b;
  }
  if (best) {
    best.d.note = 'N-truss box (verticals, alternating diagonals, one zigzag lateral diagonal per bay top and bottom), pinned, fully-stressed sizing to 0.75 over steel CHS/SHS and glulam with stress-range-driven areas.';
    return best.d;
  }
  // Fallback: Warren box with uniform S355 CHS273x10 (attempt-5 design, known to pass).
  const d = build(TW, TW.mem.map(() => Math.max(0, idxOf('S355 CHS273x10'))));
  d.note = 'Fallback: Warren box, uniform S355 CHS273x10.';
  return d;
}

function design(site, analyse) {
