    '76.1,3.2,7.33,48.8', '76.1,4,9.06,59.1', '88.9,4,10.67,96.3', '88.9,5,13.18,116.4', '114.3,4,13.86,211.1',
    '114.3,5,17.17,256.9', '139.7,5,21.16,480.5', '139.7,6.3,26.4,588.6', '168.3,5,25.65,855.8', '168.3,6.3,32.06,1053.4',
    '193.7,6.3,37.09,1630', '193.7,8,46.67,2015.5', '219.1,8,53.06,2959.6', '244.5,8,59.44,4160.4', '273,10,82.62,7154.1',
