    };
  }

  const CAND = [];
  for (const g of STEELS) {
    for (const row of CHS_D) { const p = row.split(',').map(Number); const c = steelCand(g, 'CHS', p[0], p[1], p[2], p[3]); if (c) CAND.push(c); }
    for (const row of SHS_D) { const p = row.split(',').map(Number); const c = steelCand(g, 'SHS', p[0], p[1], p[2], p[3]); if (c) CAND.push(c); }
  }
  for (const row of TIM_D) {
    const p = row.split(',');
    const A = Number(p[1]), I = Number(p[2]);
    CAND.push({
      spec: 'GL28 TIMBER' + p[0], mass: 420 * A * 1e-4, ds: 8, Aeng: A * 100,
      Aw: A * 100 * 0.96, Iw: I * 1e4 * 0.96, fyw: 22 * 0.88, Ew: 12600 * 0.88, aw: 0.49 * 1.44
    });
  }
  CAND.sort((a, b) => (a.mass - b.mass) || (b.fyw - a.fyw));
  let START = CAND.findIndex(c => c.spec === 'S355 CHS168.3x6.3');
  if (START < 0) START = Math.floor(CAND.length / 2);

  function capOf(c, L) {
    const Afy = c.Aw * c.fyw;                       // N
    const Tk = Afy / 1.17 / 1000;                   // kN
    const Ncr = Math.PI * Math.PI * c.Ew * c.Iw / (L * L * 1e6);   // N
    const lam = Math.sqrt(Afy / Math.max(Ncr, 1e-9));
    let chi = 1;
    if (lam > 0.2) {
      const phi = 0.5 * (1 + c.aw * (lam - 0.2) + lam * lam);
      chi = Math.min(1, 1 / (phi + Math.sqrt(Math.max(0, phi * phi - lam * lam))));
    }
    return { T: Tk, C: chi * Tk };
  }

  function pick(L, Tdem, Cdem, F) {
    for (let k = 0; k < CAND.length; k++) {
      const c = CAND[k];
      const cap = capOf(c, L);
      const u = Math.max(Tdem / cap.T, Cdem / cap.C);
      const uf = F * 1000 / c.Aw / c.ds;
      if (u <= TGT && uf <= TGF) return k;
    }
    return CAND.length - 1;
  }

  // ---------- N-truss topology (attempt 6, verified) ----------
