    for (const s of ['L', 'R']) {
      const B = 'B' + s;
      for (let i = 0; i < 9; i++) { add(s + i, s + (i + 1)); add(B + i, B + (i + 1)); }
      for (let i = 0; i < 10; i++) add(s + i, B + i);
      for (let i = 0; i < 9; i++) {
        if (i % 2 === 0) add(s + i, B + (i + 1)); else add(B + i, s + (i + 1));
      }
    }
    for (let i = 0; i < 10; i++) { add('L' + i, 'R' + i); add('BL' + i, 'BR' + i); }
    for (let k = 0; k < 9; k++) {
      if (k % 2 === 0) { add('L' + k, 'R' + (k + 1)); add('BL' + k, 'BR' + (k + 1)); }
      else { add('R' + k, 'L' + (k + 1)); add('BR' + k, 'BL' + (k + 1)); }
    }
    return finish(nodes, mem);
  }
  const T = topoN();

  function build(sz) {
    return {
      note: '',
      nodes: T.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: 'pin' })),
      joints: {},
      members: T.mem.map((m, j) => ({ a: m.a, b: m.b, spec: CAND[sz[j]].spec }))
    };
  }

  function num(x) { return typeof x === 'number' && isFinite(x) ? x : 0; }
  function mapMembers(r, mem) {
    if (!r || !Array.isArray(r.members) || r.members.length === 0) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    const out = [];
    for (let j = 0; j < mem.length; j++) {
      const m = mem[j];
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a] || byId[m.a + '_' + m.b] || byId[m.b + '_' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e) { out.push(null); continue; }
      out.push({
        util: num(e.util), mode: String(e.mode || ''),
        t: Math.abs(num(e.tension)), c: Math.abs(num(e.compression))
      });
    }
    return out;
  }

  function feasibleNom(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.9) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.9) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.1 * r.fMin) return false;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.2 * r.alphaCrMin) return false;
    return true;
  }
  function globBad(r) {
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.8 * r.sagLimit) return true;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.8 * r.swayLimit) return true;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.2 * r.fMin) return true;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.5 * r.alphaCrMin) return true;
    return false;
  }

  // ---------- fully-stressed sizing against worst-unit capacities ----------
  const nm = T.mem.length;
  let sz = new Array(nm).fill(START);
  const Fr = new Array(nm).fill(null);   // exact traffic stress-range force (kN) where fatigue governs
  let best = null, last = null;
  const seen = new Set();
  for (let it = 0; it < 40; it++) {
    if (Date.now() - T0 > LIMIT) break;
    const key = sz.join(',') + '|' + kap.toFixed(3) + '|' + TGT.toFixed(3);
    if (seen.has(key)) break;
    seen.add(key);
    const d = build(sz);
    last = d;
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    if (!r || r.error) break;
    if (feasibleNom(r) && (!best || r.mass < best.mass)) best = { mass: r.mass, d: d };
    const mm = mapMembers(r, T.mem);
    if (!mm) break;
    for (let j = 0; j < nm; j++) {
      const e = mm[j];
      if (!e) continue;
      if (/fatigue/i.test(e.mode) && e.util > 0) {
        const c = CAND[sz[j]];
        Fr[j] = e.util * c.ds * c.Aeng / 1000;   // kN
      }
    }
    if (typeof r.fatigueWorst === 'number') {
      if (r.fatigueWorst > 0.85) kap *= 1.12;
      else if (r.fatigueWorst < 0.5) kap = Math.max(0.2, kap * 0.97);
    }
    if (globBad(r)) TGT = Math.max(0.8, TGT * 0.95);
    const nsz = sz.slice();
    for (let j = 0; j < nm; j++) {
      const e = mm[j];
      if (!e) continue;
      const Tdem = Math.max(DEM_F * e.t, FLOOR);
      const Cdem = Math.max(DEM_F * e.c, FLOOR);
      let F = Fr[j] !== null ? Fr[j] : kap * (e.t + e.c);
      F = Math.max(DEM_F * F, 5);
      nsz[j] = pick(T.len[j], Tdem, Cdem, F);
    }
    if (nsz.every((v, j) => v === sz[j])) break;
    sz = nsz;
  }

  const out = best ? best.d : last;
  out.note = 'N-truss box sized member by member to worst-unit capacities (fy, thickness, E, imperfection draws; demands x1.05), steel wherever timber compression would fail and timber only where traffic fatigue governs, all pinned.';
  return out;
}

