  const XM = [];
  for (let i = 0; i < 9; i++) XM.push(0.5 * (X[i] + X[i + 1]));
  const TGT = 0.85;   // target utilisation against worst-unit capacities
  const DEM = 1.05;   // demand factor

  // CHS/SHS rows: D,t,A cm2,I cm4 ; TIMBER rows: name,A cm2,I weak cm4
  const CHS_D = ['33.7,2.6,2.54,3.1', '42.4,3.2,3.94,7.6', '48.3,3.2,4.53,11.6', '60.3,3.2,5.74,23.5', '60.3,4,7.07,28.2',
    '76.1,3.2,7.33,48.8', '76.1,4,9.06,59.1', '88.9,4,10.67,96.3', '88.9,5,13.18,116.4', '114.3,4,13.86,211.1',
    '114.3,5,17.17,256.9', '139.7,5,21.16,480.5', '139.7,6.3,26.4,588.6', '168.3,5,25.65,855.8', '168.3,6.3,32.06,1053.4',
    '193.7,6.3,37.09,1630', '193.7,8,46.67,2015.5', '219.1,8,53.06,2959.6', '244.5,8,59.44,4160.4', '273,10,82.62,7154.1',
    '323.9,10,98.61,12158.3', '355.6,12.5,134.74,19852.2', '406.4,12.5,154.68,30030.7', '457,16,221.67,53959.4'];
  const SHS_D = ['40,3,4.44,10.2', '50,3,5.64,20.8', '60,4,8.96,47.1', '70,4,10.56,76.9', '80,5,15,141.3', '90,5,17,205.4',
    '100,5,19,286.6', '100,8,29.44,418.4', '120,6,27.36,594.3', '140,6,32.16,964.4', '150,8,45.44,1531.9',
    '180,8,55.04,2719.7', '200,10,76,4585.3', '250,10,96,9232', '300,12.5,143.75,19840.5', '350,16,213.76,39834.9'];
  const TIM_D = ['90x180,162,1093.5', '115x225,258.75,2851.6', '140x270,378,6174', '160x315,504,10752', '190x360,684,20577',
    '190x450,855,25721.3', '215x540,1161,44722.7', '240x630,1512,72576', '280x720,2016,131712', '320x900,2880,245760'];
  const STEELS = [{ m: 'S235', fy: 235, fyF: 0.95 }, { m: 'S355', fy: 355, fyF: 0.94 },
    { m: 'S460', fy: 460, fyF: 0.93 }, { m: 'S690', fy: 690, fyF: 0.92 }];

  function steelRow(g, fam, row) {
    const q = row.split(',');
    const D = Number(q[0]), t = Number(q[1]), A = Number(q[2]), I = Number(q[3]);
    const eps2 = 235 / g.fy;
    const lim = fam === 'CHS' ? 90 * eps2 : 42 * Math.sqrt(eps2);
    const slen = fam === 'CHS' ? D / t : (D - 2 * t) / t;
    if (slen > lim) return null;
    return { spec: g.m + ' ' + fam + q[0] + 'x' + q[1], tim: false, shape: fam === 'CHS' ? 'C' : 'S',
      D: D, t: t, A: A, I: I, mass: 7850 * A * 1e-4, fy: g.fy, fyF: g.fyF };
  }

  const CAND = [];
  for (const g of STEELS) {
    for (const row of CHS_D) { const c = steelRow(g, 'CHS', row); if (c) CAND.push(c); }
    for (const row of SHS_D) { const c = steelRow(g, 'SHS', row); if (c) CAND.push(c); }
  }
  for (const row of TIM_D) {
    const p = row.split(',');
    CAND.push({ spec: 'GL28 TIMBER' + p[0], tim: true, A: Number(p[1]), I: Number(p[2]), mass: 420 * Number(p[1]) * 1e-4 });
  }
  CAND.sort((a, b) => a.mass - b.mass);
  let START = CAND.findIndex(c => c.spec === 'S355 CHS168.3x6.3');
  if (START < 0) START = Math.floor(CAND.length / 2);

  // Capacities (kN) of candidate c for member length L (m).
  // worst = worst-unit draws: strength 0.92-0.95, thickness 0.92 (+0.6 mm corrosion), E 0.97,
  // imperfection 1.5x; timber strength 0.85, E 0.85, area 0.96.
  function capAt(c, L, worst) {
    let Ae, I, fy, E, al, ds;
    if (c.tim) {
      Ae = worst ? c.A * 0.96 : c.A;
      I = worst ? c.I * 0.96 : c.I;
      fy = worst ? 22 * 0.85 : 22;
      E = worst ? 12600 * 0.85 : 12600;
      al = worst ? 0.49 * 1.5 : 0.49;
      ds = 8;
    } else {
      const te = worst ? 0.92 * c.t - 0.6 : c.t - 0.6;
      const k = c.shape === 'C' ? Math.PI : 4;
      Ae = k * te * (c.D - te) / 100;          // cm2
      I = c.I * Ae / c.A;
      fy = worst ? c.fy * c.fyF : c.fy;
      E = worst ? 210000 * 0.97 : 210000;
      al = worst ? 0.21 * 1.5 : 0.21;
      ds = 90;
    }
    const Afy = Ae * fy / 10;                  // kN
    const Tc = Afy / 1.17;
    const Ncr = 9.8696e-5 * E * I / (L * L);   // kN, I in cm4, L in m
    const lam = Math.sqrt(Afy / Math.max(Ncr, 1e-9));
    let chi = 1;
    if (lam > 0.2) {
      const phi = 0.5 * (1 + al * (lam - 0.2) + lam * lam);
      chi = Math.min(1, 1 / (phi + Math.sqrt(Math.max(0, phi * phi - lam * lam))));
    }
    return { T: Tc, C: chi * Tc, F: Ae * ds / 10 };
  }

  // lightest candidate whose worst-unit capacities meet the nominal demands / target
  function pickCand(L, Dt, Dc, Df, tg) {
    for (let k = 0; k < CAND.length; k++) {
      const w = capAt(CAND[k], L, true);
      if (w.T >= Dt / tg && w.C >= Dc / tg && (Df <= 0 || w.F >= Df / tg)) return k;
    }
    return CAND.length - 1;
  }

  function finish(nodes, mem) {
    const P = {};
    for (let i = 0; i < 10; i++) { P['L' + i] = [X[i], 0, ZL]; P['R' + i] = [X[i], 0, ZR]; }
    for (const n of nodes) P[n.id] = [n.x, n.y, n.z];
    const len = mem.map(m => {
      const p = P[m.a], q = P[m.b];
      return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
    });
    return { nodes: nodes, mem: mem, len: len };
  }

  // Topology A: closed box. Verticals and cross-girders at every deck node, zigzag walls,
  // zigzag bottom lateral, top lateral X (xTop) or zigzag, diagonals in both end faces.
  function topoA(xTop) {
    const nodes = [], mem = [];
    const add = (a, b) => mem.push({ a: a, b: b });
    for (let i = 0; i < 10; i++) {
      nodes.push({ id: 'BL' + i, x: X[i], y: -H, z: ZL });
      nodes.push({ id: 'BR' + i, x: X[i], y: -H, z: ZR });
    }
    for (let i = 0; i < 9; i++) {
      add('L' + i, 'L' + (i + 1)); add('R' + i, 'R' + (i + 1));
      add('BL' + i, 'BL' + (i + 1)); add('BR' + i, 'BR' + (i + 1));
    }
    for (let i = 0; i < 10; i++) {
      add('L' + i, 'BL' + i); add('R' + i, 'BR' + i);
      add('L' + i, 'R' + i); add('BL' + i, 'BR' + i);
    }
    for (let i = 0; i < 9; i++) {
      if (xTop) { add('L' + i, 'R' + (i + 1)); add('R' + i, 'L' + (i + 1)); }
      else if (i % 2 === 0) add('L' + i, 'R' + (i + 1));
      else add('R' + i, 'L' + (i + 1));
      if (i % 2 === 0) {
        add('L' + i, 'BL' + (i + 1)); add('R' + i, 'BR' + (i + 1));
        add('BL' + i, 'BR' + (i + 1));
      } else {
        add('BL' + i, 'L' + (i + 1)); add('BR' + i, 'R' + (i + 1));
        add('BR' + i, 'BL' + (i + 1));
      }
    }
    add('L0', 'BR0'); add('L9', 'BR9');
    return finish(nodes, mem);
  }

  // Topology B (attempt-6 Warren box, known to pass)
  function topoW(xTop, endD) {
    const nodes = [], mem = [];
    const add = (a, b) => mem.push({ a: a, b: b });
    for (let i = 0; i < 9; i++) {
      nodes.push({ id: 'BL' + i, x: XM[i], y: -H, z: ZL });
      nodes.push({ id: 'BR' + i, x: XM[i], y: -H, z: ZR });
    }
    for (const s of ['L', 'R']) {
      const B = 'B' + s;
      for (let i = 0; i < 9; i++) add(s + i, s + (i + 1));
      for (let i = 0; i < 8; i++) add(B + i, B + (i + 1));
      for (let i = 0; i < 9; i++) { add(s + i, B + i); add(B + i, s + (i + 1)); }
    }
    for (let i = 0; i < 10; i++) add('L' + i, 'R' + i);
    for (let k = 0; k < 9; k++) {
      if (xTop) { add('L' + k, 'R' + (k + 1)); add('R' + k, 'L' + (k + 1)); }
      else if (k % 2 === 0) add('L' + k, 'R' + (k + 1));
      else add('R' + k, 'L' + (k + 1));
    }
    for (let i = 0; i < 9; i++) add('BL' + i, 'BR' + i);
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) add('BL' + i, 'BR' + (i + 1)); else add('BR' + i, 'BL' + (i + 1));
    }
    if (endD) { add('L0', 'BR0'); add('R0', 'BL0'); add('L9', 'BR8'); add('R9', 'BL8'); }
    return finish(nodes, mem);
  }

  function build(Tp, sz, note) {
    return {
      note: note || '',
      nodes: Tp.nodes.map(n => ({ id: n.id, x: n.x, y: n.y, z: n.z, joint: 'pin' })),
      joints: {},
      members: Tp.mem.map((m, j) => ({ a: m.a, b: m.b, spec: CAND[sz[j]].spec }))
    };
  }

  function num(x) { return typeof x === 'number' && isFinite(x) ? x : 0; }

  function mapMembers(r, mem) {
    if (!r || !Array.isArray(r.members) || r.members.length === 0) return null;
    const byId = {};
    for (const e of r.members) if (e && e.id !== undefined) byId[String(e.id)] = e;
    const out = [];
    for (let j = 0; j < mem.length; j++) {
      const m = mem[j];
      let e = byId[m.a + '-' + m.b] || byId[m.b + '-' + m.a] || byId[m.a + '_' + m.b] || byId[m.b + '_' + m.a];
      if (!e && r.members.length === mem.length) e = r.members[j];
      if (!e) { out.push(null); continue; }
      out.push({
        util: num(e.util), mode: String(e.mode || ''),
        t: Math.abs(num(e.tension)), c: Math.abs(num(e.compression))
      });
    }
    return out;
  }

  function strictOk(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > 0.85) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > 0.85) return false;
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.8 * r.sagLimit) return false;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.8 * r.swayLimit) return false;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.15 * r.fMin) return false;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.25 * r.alphaCrMin) return false;
    return true;
  }

  function globBad(r) {
    if (typeof r.sag === 'number' && typeof r.sagLimit === 'number' && r.sag > 0.7 * r.sagLimit) return true;
    if (typeof r.sway === 'number' && typeof r.swayLimit === 'number' && r.sway > 0.7 * r.swayLimit) return true;
    if (typeof r.frequency === 'number' && typeof r.fMin === 'number' && r.frequency < 1.25 * r.fMin) return true;
    if (typeof r.alphaCr === 'number' && typeof r.alphaCrMin === 'number' && r.alphaCr < 1.5 * r.alphaCrMin) return true;
    return false;
  }

  // Fully-stressed sizing against worst-unit capacities, driven by analyse feedback.
  function runTopo(Tp, tEnd) {
    const nm = Tp.mem.length;
    let sz = new Array(nm).fill(START);
    const FR = new Array(nm).fill(0);     // persistent traffic stress-range demand (kN)
    let g = 1.0;
    let best = null;
    const seen = {};
    for (let it = 0; it < 45; it++) {
      if (Date.now() > tEnd) break;
      const key = sz.join(',') + '|' + g.toFixed(3);
      if (seen[key]) break;
      seen[key] = 1;
      const d = build(Tp, sz, '');
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      if (typeof r.failure === 'string' && /mechanism/i.test(r.failure)) break;
      if (strictOk(r) && (!best || r.mass < best.mass)) best = { mass: r.mass, d: d };
      const mm = mapMembers(r, Tp.mem);
      if (!mm) break;
      if (globBad(r)) g = Math.max(0.6, g * 0.93);
      const tg = TGT * g;
      const nsz = sz.slice();
      for (let j = 0; j < nm; j++) {
        const e = mm[j];
        if (!e) continue;
        const L = Tp.len[j];
        const cur = CAND[sz[j]];
        const nom = capAt(cur, L, false);
        const fat = /fatigue/i.test(e.mode) && e.util > 0;
        let Dt = e.t, Dc = e.c, Df = FR[j];
        if (fat) {
          FR[j] = e.util * nom.F;
          Df = FR[j];
        } else if (e.util > 0) {
          if (Dc > Dt) Dc = Math.max(Dc, e.util * nom.C);
          else Dt = Math.max(Dt, e.util * nom.T);
        }
        Dt = Math.max(DEM * Dt, 3);
        Dc = Math.max(DEM * Dc, 3);
        Df = DEM * Df;
        nsz[j] = pickCand(L, Dt, Dc, Df, tg);
      }
      if (nsz.every((v, j) => v === sz[j])) break;
      sz = nsz;
    }
    return best;
  }

  const TA = topoA(true);
  const TZ = topoA(false);
  const TB = topoW(true, true);
  const tops = [TA, TZ, TB];
  let best = null;
  for (let i = 0; i < tops.length; i++) {
    const remaining = TOTAL - (Date.now() - T0);
    if (remaining < 4000) break;
    const tEnd = Date.now() + remaining / (tops.length - i);
    const b = runTopo(tops[i], tEnd);
    if (b && (!best || b.mass < best.mass)) best = b;
  }
  if (best) {
    best.d.note = 'Closed box (verticals and cross-girders at every deck node, zigzag walls, top X lateral, end-face diagonals), all pinned, fully-stressed to worst-unit capacities with stress-range-driven timber/steel choice.';
    return best.d;
  }
  // Fallback: heavy uniform S460 CHS323.9x10 on the closed box.
  let fb = CAND.findIndex(c => c.spec === 'S460 CHS323.9x10');
  if (fb < 0) fb = CAND.length - 1;
  return build(TA, new Array(TA.mem.length).fill(fb), 'Fallback: closed box, uniform S460 CHS323.9x10.');
}
